insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary) values
('Мединский курс (Том 2)', '1', 'إِنَّ وَأَخَوَاتُهَا (إِنَّ и её сёстры)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">إِنَّ وَأَخَوَاتُهَا</span><p class="rule-study-text">إِنَّ и её сёстры. В шархе этот урок раскрывает إِنَّ وَأَخَوَاتُهَا: эти частицы входят только в الْجُمْلَةُ الِاسْمِيَّةُ, ставят бывший مُبْتَدَأٌ как своё имя в نَصْب, а خَبَرٌ оставляют в رَفْع. Каждая частица имеет свой смысл: усиление, «что», противопоставление, уподобление, надежда/опасение или пожелание.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِنَّ وَأَخَوَاتُهَا</span><span class="rule-term-ru">إِنَّ и её сёстры</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِنَّ</span><span class="rule-term-ru">إِنَّ — «поистине, воистину»; حَرْفُ تَوْكِيدٍ وَنَصْبٍ: усиливает утверждение и ставит своё имя в نَصْب.</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">مُبْتَدَأٌ</span><span class="rule-term-ru">مُبْتَدَأٌ — подлежащее именного предложения; обычно مَرْفُوعٍ.</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar" dir="rtl" lang="ar">خَبَرٌ</span><span class="rule-term-ru">خَبَرٌ — сказуемое/сообщение об مُبْتَدَأٌ; обычно مَرْفُوعٍ.</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَنَّ</span><span class="rule-term-ru">أَنَّ — что; придаточное сообщение; اِسْمٌ أَنَّ в نَصْب, خَبَرٌ أَنَّ в رَفْع.</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَكِنَّ</span><span class="rule-term-ru">لَكِنَّ — но, однако; противопоставление; имя в نَصْب, خَبَرٌ в رَفْع.</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">كَأَنَّ</span><span class="rule-term-ru">كَأَنَّ — как будто, словно; уподобление/предположение; имя в نَصْب, خَبَرٌ в رَفْع.</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَعَلَّ</span><span class="rule-term-ru">لَعَلَّ — может быть, возможно, надеюсь; надежда или опасение; имя в نَصْب, خَبَرٌ в رَفْع.</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَيْتَ</span><span class="rule-term-ru">لَيْتَ — о если бы, хотелось бы; пожелание; имя в نَصْب, خَبَرٌ в رَفْع.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите именное предложение: مُبْتَدَأٌ + خَبَرٌ.</li><li>Поставьте после частицы её имя в نَصْب.</li><li>Оставьте её خَبَرٌ в رَفْع и переведите смысл самой частицы.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">إِنَّ الْمَاءَ بَارِدٌ.</span><span class="rule-example-ru">Поистине, вода холодная.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">سَمِعْتُ أَنَّ الْمُدَرِّسَ مَرِيضٌ.</span><span class="rule-example-ru">Я услышал, что учитель болен.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">السَّيَّارَةُ قَدِيمَةٌ، لَكِنَّهَا قَوِيَّةٌ.</span><span class="rule-example-ru">Машина старая, но она крепкая.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">كَأَنَّ الْمَسْجِدَ مَدْرَسَةٌ.</span><span class="rule-example-ru">Как будто мечеть — школа.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لَعَلَّ الِاخْتِبَارَ سَهْلٌ.</span><span class="rule-example-ru">Возможно, экзамен лёгкий.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لَيْتَ مُحَمَّدًا طَبِيبٌ.</span><span class="rule-example-ru">Хотелось бы, чтобы Мухаммад был врачом.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Главная ошибка: после إِنَّ писать имя с даммой. Правильно: إِنَّ الطَّالِبَ مُجْتَهِدٌ — الطَّالِبَ в نَصْب, مُجْتَهِدٌ в رَفْع.<br><br><b>Самопроверка.</b> После إِنَّ нельзя оставлять имя с даммой: правильно إِنَّ الْمَاءَ / إِنَّ الطَّالِبَ. Дамма остаётся у خَبَرٌ: بَارِدٌ، مُجْتَهِدٌ.</div></div>', '1', 'rule', 'إِنَّ и её сёстры. В шархе этот урок раскрывает إِنَّ وَأَخَوَاتُهَا: эти частицы входят только в الْجُمْلَةُ الِاسْمِيَّةُ, ставят бывший مُبْتَدَأٌ как своё имя в نَصْب, а خَبَرٌ оставляют в رَفْع. Каждая частица имеет свой смы'),
('Мединский курс (Том 2)', '1', 'أَمْ وَهَمْزَةُ التَّعْيِينِ (أَمْ и вопрос с выбором)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَمْ وَهَمْزَةُ التَّعْيِينِ</span><p class="rule-study-text">أَمْ и вопрос с выбором. В вопросе с двумя вариантами перед первым ставится أَ, между вариантами — أَمْ. Ответом должен быть выбранный вариант, а не «да» или «нет».</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَمْ وَهَمْزَةُ التَّعْيِينِ</span><span class="rule-term-ru">أَمْ и вопрос с выбором</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أَمِنَ الْهِنْدِ أَنْتَ أَمْ مِنْ بَاكِسْتَانَ؟</span><span class="rule-example-ru">Ты из Индии или из Пакистана?</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '2', 'rule', 'أَمْ и вопрос с выбором. В вопросе с двумя вариантами перед первым ставится أَ, между вариантами — أَمْ. Ответом должен быть выбранный вариант, а не «да» или «нет».'),
('Мединский курс (Том 2)', '1', 'ذُو وَذَاتُ (обладающий и обладающая)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">ذُو وَذَاتُ</span><p class="rule-study-text">обладающий и обладающая. ذُو означает «обладающий» и входит в идафу. Женская форма — ذَاتُ, мужское множественное — ذَوُو, женское — ذَوَاتُ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ذُو وَذَاتُ</span><span class="rule-term-ru">обладающий и обладающая</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите два связанных имени.</li><li>Первое — مُضَافٌ, второе — مُضَافٌ إِلَيْهِ.</li><li>У второго члена всегда جَرّ, а первый не принимает танвин.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا رَجُلٌ ذُو خُلُقٍ.</span><span class="rule-example-ru">Это человек с хорошим нравом.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هَذِهِ طَالِبَةٌ ذَاتُ عِلْمٍ.</span><span class="rule-example-ru">Это студентка, обладающая знанием.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Первый член идафы не получает одновременно танвин и связь принадлежности.</div></div>', '3', 'rule', 'обладающий и обладающая. ذُو означает «обладающий» и входит в идафу. Женская форма — ذَاتُ, мужское множественное — ذَوُو, женское — ذَوَاتُ.'),
('Мединский курс (Том 2)', '1', 'الِاسْمُ الْمَنْقُوصُ (недостаточное имя)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الِاسْمُ الْمَنْقُوصُ</span><p class="rule-study-text">недостаточное имя. Имя на ي, перед которой стоит касра, называется недостаточным. В неопределенной форме именительного и родительного падежей ي опускается и заменяется танвином.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الِاسْمُ الْمَنْقُوصُ</span><span class="rule-term-ru">недостаточное имя</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите مَنْعُوتٌ — определяемое слово.</li><li>Поставьте после него نَعْتٌ.</li><li>Согласуйте نَعْتٌ в падеже, определённости, роде и числе.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا قَاضٍ.</span><span class="rule-example-ru">Это судья.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">سَلَّمْتُ عَلَى قَاضٍ.</span><span class="rule-example-ru">Я поприветствовал судью.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя переводить прилагательное отдельно от определяемого слова: его окончание зависит от مَنْعُوت.</div></div>', '4', 'rule', 'недостаточное имя. Имя на ي, перед которой стоит касра, называется недостаточным. В неопределенной форме именительного и родительного падежей ي опускается и заменяется танвином.'),
('Мединский курс (Том 2)', '1', 'مِائَةٌ وَأَلْفٌ (числа сто и тысяча)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مِائَةٌ وَأَلْفٌ</span><p class="rule-study-text">числа сто и тысяча. После مِائَة и أَلْف считаемое имя стоит в единственном числе и родительном падеже. Форма числа не зависит от рода предмета.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مِائَةٌ وَأَلْفٌ</span><span class="rule-term-ru">числа сто и тысяча</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число и разряд.</li><li>Проверьте род числительного и род الْمَعْدُودُ.</li><li>Поставьте الْمَعْدُودُ в нужное число и падеж.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مِائَةُ كِتَابٍ.</span><span class="rule-example-ru">Сто книг.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أَلْفُ سَيَّارَةٍ.</span><span class="rule-example-ru">Тысяча автомобилей.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя применять одно правило ко всем числам: ٣–١٠, ١١–١٩, десятки, сотни и тысячи ведут себя по-разному.</div></div>', '5', 'rule', 'числа сто и тысяча. После مِائَة и أَلْف считаемое имя стоит в единственном числе и родительном падеже. Форма числа не зависит от рода предмета.'),
('Мединский курс (Том 2)', '2', 'لَيْسَ وَضَمَائِرُهَا (لَيْسَ и ее формы)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">لَيْسَ وَضَمَائِرُهَا</span><p class="rule-study-text">لَيْسَ и ее формы. لَيْسَ отрицает состояние в настоящем. Ее имя именительное, сказуемое винительное. Запомните: لَسْتُ، لَسْنَا، لَسْتَ، لَيْسَ، لَيْسَتْ، لَيْسُوا، لَسْنَ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَيْسَ وَضَمَائِرُهَا</span><span class="rule-term-ru">لَيْسَ и ее формы</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَيْسَ</span><span class="rule-term-ru">لَيْسَ — «не является, нет»; её имя в رَفْع, خَبَرٌ в نَصْب.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите имя этой частицы/глагола.</li><li>Проверьте: имя в رَفْع.</li><li>Проверьте: خَبَرٌ в نَصْب, даже если смысл по-русски похож на обычное сказуемое.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لَسْتُ مُتْعَبًا.</span><span class="rule-example-ru">Я не устал.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لَسْنَ غَائِبَاتٍ.</span><span class="rule-example-ru">Они, женщины, не отсутствуют.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не оставляйте خَبَرٌ لَيْسَ или خَبَرٌ كَانَ в рафʿе: это место требует نَصْب.</div></div>', '1', 'rule', 'لَيْسَ и ее формы. لَيْسَ отрицает состояние в настоящем. Ее имя именительное, сказуемое винительное. Запомните: لَسْتُ، لَسْنَا، لَسْتَ، لَيْسَ، لَيْسَتْ، لَيْسُوا، لَسْنَ.'),
('Мединский курс (Том 2)', '2', 'الْبَاءُ الزَّائِدَةُ فِي خَبَرِ لَيْسَ (усилительная بِ в сказуемом لَيْسَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْبَاءُ الزَّائِدَةُ فِي خَبَرِ لَيْسَ</span><p class="rule-study-text">усилительная بِ в сказуемом لَيْسَ. К сказуемому может присоединяться بِ. По форме слово становится родительным, но синтаксически остается сказуемым в винительном положении.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْبَاءُ الزَّائِدَةُ فِي خَبَرِ لَيْسَ</span><span class="rule-term-ru">усилительная بِ в сказуемом لَيْسَ</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَيْسَ</span><span class="rule-term-ru">لَيْسَ — «не является, нет»; её имя в رَفْع, خَبَرٌ в نَصْب.</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar" dir="rtl" lang="ar">خَبَرٌ</span><span class="rule-term-ru">خَبَرٌ — сказуемое/сообщение об مُبْتَدَأٌ; обычно مَرْفُوعٍ.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите имя этой частицы/глагола.</li><li>Проверьте: имя в رَفْع.</li><li>Проверьте: خَبَرٌ в نَصْب, даже если смысл по-русски похож на обычное сказуемое.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لَيْسَ الطَّالِبُ بِغَائِبٍ.</span><span class="rule-example-ru">Студент вовсе не отсутствует.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не оставляйте خَبَرٌ لَيْسَ или خَبَرٌ كَانَ в рафʿе: это место требует نَصْب.</div></div>', '2', 'rule', 'усилительная بِ в сказуемом لَيْسَ. К сказуемому может присоединяться بِ. По форме слово становится родительным, но синтаксически остается сказуемым в винительном положении.'),
('Мединский курс (Том 2)', '2', 'تَقْدِيمُ خَبَرِ إِنَّ (сказуемое إِنَّ перед ее именем)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">تَقْدِيمُ خَبَرِ إِنَّ</span><p class="rule-study-text">сказуемое إِنَّ перед ее именем. Сказуемое-обстоятельство или сочетание с предлогом может стоять перед именем إِنَّ. Имя все равно остается винительным.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">تَقْدِيمُ خَبَرِ إِنَّ</span><span class="rule-term-ru">сказуемое إِنَّ перед ее именем</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِنَّ</span><span class="rule-term-ru">إِنَّ — «поистине, воистину»; حَرْفُ تَوْكِيدٍ وَنَصْبٍ: усиливает утверждение и ставит своё имя в نَصْب.</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">خَبَرُ إِنَّ</span><span class="rule-term-ru">خَبَرُ إِنَّ — сказуемое частицы إِنَّ; бывший خَبَرٌ, остаётся в رَفْع.</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar" dir="rtl" lang="ar">خَبَرٌ</span><span class="rule-term-ru">خَبَرٌ — сказуемое/сообщение об مُبْتَدَأٌ; обычно مَرْفُوعٍ.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите именное предложение: مُبْتَدَأٌ + خَبَرٌ.</li><li>Поставьте после частицы её имя в نَصْب.</li><li>Оставьте её خَبَرٌ в رَفْع и переведите смысл самой частицы.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">إِنَّ فِي الْفَصْلِ طَالِبًا.</span><span class="rule-example-ru">Поистине, в классе есть студент.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Главная ошибка: после إِنَّ писать имя с даммой. Правильно: إِنَّ الطَّالِبَ مُجْتَهِدٌ — الطَّالِبَ в نَصْب, مُجْتَهِدٌ в رَفْع.</div></div>', '3', 'rule', 'сказуемое إِنَّ перед ее именем. Сказуемое-обстоятельство или сочетание с предлогом может стоять перед именем إِنَّ. Имя все равно остается винительным.'),
('Мединский курс (Том 2)', '3', 'اسْمُ التَّفْضِيلِ (сравнительная и превосходная степень)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">اسْمُ التَّفْضِيلِ</span><p class="rule-study-text">сравнительная и превосходная степень. Модель أَفْعَلُ передает «более» или «самый». С مِنْ это сравнение, а в идафе или с ال — превосходная степень.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ التَّفْضِيلِ</span><span class="rule-term-ru">сравнительная и превосходная степень</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">خَالِدٌ أَطْوَلُ مِنْ حَامِدٍ.</span><span class="rule-example-ru">Халид выше Хамида.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هُوَ أَحْسَنُ الطُّلَّابِ.</span><span class="rule-example-ru">Он лучший из студентов.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '1', 'rule', 'сравнительная и превосходная степень. Модель أَفْعَلُ передает «более» или «самый». С مِنْ это сравнение, а в идафе или с ال — превосходная степень.'),
('Мединский курс (Том 2)', '3', 'لَكِنَّ وَكَأَنَّ (частицы «но» и «как будто»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">لَكِنَّ وَكَأَنَّ</span><p class="rule-study-text">частицы «но» и «как будто». لَكِنَّ выражает противопоставление, كَأَنَّ — уподобление. Они действуют как إِنَّ: имя винительное, сказуемое именительное.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَكِنَّ وَكَأَنَّ</span><span class="rule-term-ru">частицы «но» и «как будто»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِنَّ</span><span class="rule-term-ru">إِنَّ — «поистине, воистину»; حَرْفُ تَوْكِيدٍ وَنَصْبٍ: усиливает утверждение и ставит своё имя в نَصْب.</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَكِنَّ</span><span class="rule-term-ru">لَكِنَّ — «однако, но»; حَرْفُ اسْتِدْرَاكٍ وَنَصْبٍ: вводит противопоставление.</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">كَأَنَّ</span><span class="rule-term-ru">كَأَنَّ — «как будто, словно»; حَرْفُ تَشْبِيهٍ وَظَنٍّ.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите именное предложение: مُبْتَدَأٌ + خَبَرٌ.</li><li>Поставьте после частицы её имя в نَصْب.</li><li>Оставьте её خَبَرٌ в رَفْع и переведите смысл самой частицы.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">الْبَيْتُ صَغِيرٌ لَكِنَّهُ جَمِيلٌ.</span><span class="rule-example-ru">Дом маленький, но красивый.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">كَأَنَّ الْقَمَرَ مِصْبَاحٌ.</span><span class="rule-example-ru">Луна словно светильник.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Главная ошибка: после إِنَّ писать имя с даммой. Правильно: إِنَّ الطَّالِبَ مُجْتَهِدٌ — الطَّالِبَ в نَصْب, مُجْتَهِدٌ в رَفْع.</div></div>', '2', 'rule', 'частицы «но» и «как будто». لَكِنَّ выражает противопоставление, كَأَنَّ — уподобление. Они действуют как إِنَّ: имя винительное, сказуемое именительное.'),
('Мединский курс (Том 2)', '3', 'الْأَعْدَادُ ١١–٩٠ (числа 11–90)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْأَعْدَادُ ١١–٩٠</span><p class="rule-study-text">числа 11–90. В 11 и 12 обе части согласуются с родом. В 13–19 первая часть противоположна роду, а عَشَر/عَشْرَة согласуется. Десятки склоняются через ـُونَ/ـِينَ; считаемое слово единственное винительное.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الْأَعْدَادُ ١١–٩٠</span><span class="rule-term-ru">числа 11–90</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число и разряд.</li><li>Проверьте род числительного и род الْمَعْدُودُ.</li><li>Поставьте الْمَعْدُودُ в нужное число и падеж.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ثَلَاثَةَ عَشَرَ طَالِبًا.</span><span class="rule-example-ru">Тринадцать студентов.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">رَأَيْتُ عِشْرِينَ طَالِبًا.</span><span class="rule-example-ru">Я увидел двадцать студентов.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя применять одно правило ко всем числам: ٣–١٠, ١١–١٩, десятки, сотни и тысячи ведут себя по-разному.</div></div>', '3', 'rule', 'числа 11–90. В 11 и 12 обе части согласуются с родом. В 13–19 первая часть противоположна роду, а عَشَر/عَشْرَة согласуется. Десятки склоняются через ـُونَ/ـِينَ; считаемое слово единственное винительное.'),
('Мединский курс (Том 2)', '3', 'الْعَدَدُ التَّرْتِيبِيُّ (порядковые числительные)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْعَدَدُ التَّرْتِيبِيُّ</span><p class="rule-study-text">порядковые числительные. Порядковое числительное является прилагательным и согласуется с существительным в роде, определенности и падеже.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الْعَدَدُ التَّرْتِيبِيُّ</span><span class="rule-term-ru">порядковые числительные</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الْعَدَدُ</span><span class="rule-term-ru">الْعَدَدُ — числительное.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число и разряд.</li><li>Проверьте род числительного и род الْمَعْدُودُ.</li><li>Поставьте الْمَعْدُودُ в нужное число и падеж.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">الدَّرْسُ الثَّالِثُ.</span><span class="rule-example-ru">Третий урок.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">الصَّفْحَةُ الْخَامِسَةُ.</span><span class="rule-example-ru">Пятая страница.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя применять одно правило ко всем числам: ٣–١٠, ١١–١٩, десятки, сотни и тысячи ведут себя по-разному.</div></div>', '4', 'rule', 'порядковые числительные. Порядковое числительное является прилагательным и согласуется с существительным в роде, определенности и падеже.'),
('Мединский курс (Том 2)', '3', 'الِاسْتِفْهَامُ الْمَنْفِيُّ وَأَيُّهُمَا (отрицательный вопрос и «который из двух?»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الِاسْتِفْهَامُ الْمَنْفِيُّ وَأَيُّهُمَا</span><p class="rule-study-text">отрицательный вопрос и «который из двух?». بَلَى отменяет отрицание и означает «да, наоборот», а نَعَمْ подтверждает отрицание. أَيُّهُمَا требует выбрать одного из двух.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الِاسْتِفْهَامُ الْمَنْفِيُّ وَأَيُّهُمَا</span><span class="rule-term-ru">отрицательный вопрос и «который из двух?»</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أَلَيْسَ هَذَا كِتَابَكَ؟ بَلَى.</span><span class="rule-example-ru">Разве это не твоя книга? Да, моя.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أَيُّهُمَا أَكْبَرُ؟</span><span class="rule-example-ru">Который из них двоих старше?</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '5', 'rule', 'отрицательный вопрос и «который из двух?». بَلَى отменяет отрицание и означает «да, наоборот», а نَعَمْ подтверждает отрицание. أَيُّهُمَا требует выбрать одного из двух.'),
('Мединский курс (Том 2)', '4', 'إِسْنَادُ الْفِعْلِ الْمَاضِي (спряжение прошедшего времени)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">إِسْنَادُ الْفِعْلِ الْمَاضِي</span><p class="rule-study-text">спряжение прошедшего времени. Основа получает окончания лица и числа: ـْتُ، ـْنَا، ـْتَ، ـْتِ، ـَ، ـَتْ، ـُوا، ـْنَ. Окончание сразу указывает исполнителя.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِسْنَادُ الْفِعْلِ الْمَاضِي</span><span class="rule-term-ru">спряжение прошедшего времени</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْفِعْلُ الْمَاضِي</span><span class="rule-term-ru">الْفِعْلُ الْمَاضِي — глагол прошедшего времени.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число и разряд.</li><li>Проверьте род числительного и род الْمَعْدُودُ.</li><li>Поставьте الْمَعْدُودُ в нужное число и падеж.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ذَهَبْتُ.</span><span class="rule-example-ru">Я пошел.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ذَهَبُوا.</span><span class="rule-example-ru">Они пошли.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ذَهَبْنَ.</span><span class="rule-example-ru">Они, женщины, пошли.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя применять одно правило ко всем числам: ٣–١٠, ١١–١٩, десятки, сотни и тысячи ведут себя по-разному.</div></div>', '1', 'rule', 'спряжение прошедшего времени. Основа получает окончания лица и числа: ـْتُ، ـْنَا، ـْتَ، ـْتِ، ـَ، ـَتْ، ـُوا، ـْنَ. Окончание сразу указывает исполнителя.'),
('Мединский курс (Том 2)', '4', 'مَا النَّافِيَةُ (отрицание прошедшего через مَا)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مَا النَّافِيَةُ</span><p class="rule-study-text">отрицание прошедшего через مَا. مَا ставится перед прошедшим глаголом и не меняет его форму.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا النَّافِيَةُ</span><span class="rule-term-ru">отрицание прошедшего через مَا</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مَا ذَهَبَ حَامِدٌ.</span><span class="rule-example-ru">Хамид не пошел.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '2', 'rule', 'отрицание прошедшего через مَا. مَا ставится перед прошедшим глаголом и не меняет его форму.'),
('Мединский курс (Том 2)', '4', 'لِأَنَّ (союз «потому что»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">لِأَنَّ</span><p class="rule-study-text">союз «потому что». لِأَنَّ вводит причину и действует как إِنَّ. Присоединенное местоимение или явное имя является ее именем.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لِأَنَّ</span><span class="rule-term-ru">союз «потому что»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِنَّ</span><span class="rule-term-ru">إِنَّ — «поистине, воистину»; حَرْفُ تَوْكِيدٍ وَنَصْبٍ: усиливает утверждение и ставит своё имя в نَصْب.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите именное предложение: مُبْتَدَأٌ + خَبَرٌ.</li><li>Поставьте после частицы её имя в نَصْب.</li><li>Оставьте её خَبَرٌ в رَفْع и переведите смысл самой частицы.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">غِبْتُ لِأَنَّنِي مَرِيضٌ.</span><span class="rule-example-ru">Я отсутствовал, потому что болен.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Главная ошибка: после إِنَّ писать имя с даммой. Правильно: إِنَّ الطَّالِبَ مُجْتَهِدٌ — الطَّالِبَ в نَصْب, مُجْتَهِدٌ в رَفْع.</div></div>', '3', 'rule', 'союз «потому что». لِأَنَّ вводит причину и действует как إِنَّ. Присоединенное местоимение или явное имя является ее именем.'),
('Мединский курс (Том 2)', '5', 'الْفَاعِلُ وَالْمَفْعُولُ بِهِ (исполнитель и прямое дополнение)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْفَاعِلُ وَالْمَفْعُولُ بِهِ</span><p class="rule-study-text">исполнитель и прямое дополнение. Исполнитель действия стоит в именительном падеже, а предмет действия — в винительном. При порядке «глагол + явный исполнитель» глагол обычно остается единственным.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْفَاعِلُ وَالْمَفْعُولُ بِهِ</span><span class="rule-term-ru">исполнитель и прямое дополнение</span></div><div class="rule-meaning-card rule-term-role"><span class="rule-term-ar" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-term-ru">مَفْعُولٌ بِهِ — прямое дополнение; обычно مَنْصُوب.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">كَتَبَ الطَّالِبُ الدَّرْسَ.</span><span class="rule-example-ru">Студент написал урок.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">كَتَبَ الطُّلَّابُ الدَّرْسَ.</span><span class="rule-example-ru">Студенты написали урок.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '1', 'rule', 'исполнитель и прямое дополнение. Исполнитель действия стоит в именительном падеже, а предмет действия — в винительном. При порядке «глагол + явный исполнитель» глагол обычно остается единственным.'),
('Мединский курс (Том 2)', '5', 'ضَمَائِرُ الرَّفْعِ الْمُتَّصِلَةُ (слитные местоимения-исполнители)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">ضَمَائِرُ الرَّفْعِ الْمُتَّصِلَةُ</span><p class="rule-study-text">слитные местоимения-исполнители. تَاءُ الْفَاعِلِ, نا, أَلْفٌ الِاثْنَيْنِ, وَاوٌ الْجَمَاعَةِ и نُونٌ النِّسْوَةِ присоединяются к глаголу и сами обозначают исполнителя.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">ضَمَائِرُ الرَّفْعِ الْمُتَّصِلَةُ</span><span class="rule-term-ru">слитные местоимения-исполнители</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">كَتَبْتُمْ.</span><span class="rule-example-ru">Вы написали.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">كَتَبْنَ.</span><span class="rule-example-ru">Они, женщины, написали.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '2', 'rule', 'слитные местоимения-исполнители. تَاءُ الْفَاعِلِ, نا, أَلْفٌ الِاثْنَيْنِ, وَاوٌ الْجَمَاعَةِ и نُونٌ النِّسْوَةِ присоединяются к глаголу и сами обозначают исполнителя.'),
('Мединский курс (Том 2)', '5', 'ضَمَائِرُ النَّصْبِ الْمُتَّصِلَةُ (слитные местоимения-дополнения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">ضَمَائِرُ النَّصْبِ الْمُتَّصِلَةُ</span><p class="rule-study-text">слитные местоимения-дополнения. ـنِي، ـنَا، ـكَ، ـهُ، ـهَا، ـهُمْ и другие формы присоединяются к глаголу как прямое дополнение.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">ضَمَائِرُ النَّصْبِ الْمُتَّصِلَةُ</span><span class="rule-term-ru">слитные местоимения-дополнения</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">رَأَيْتُهُ.</span><span class="rule-example-ru">Я увидел его.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">سَأَلَنَا الْمُدَرِّسُ.</span><span class="rule-example-ru">Учитель спросил нас.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '3', 'rule', 'слитные местоимения-дополнения. ـنِي، ـنَا، ـكَ، ـهُ، ـهَا، ـهُمْ и другие формы присоединяются к глаголу как прямое дополнение.'),
('Мединский курс (Том 2)', '5', 'تَاءُ التَّأْنِيثِ السَّاكِنَةُ (показатель женского рода в прошедшем)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">تَاءُ التَّأْنِيثِ السَّاكِنَةُ</span><p class="rule-study-text">показатель женского рода в прошедшем. С явным исполнителем женского рода прошедший глагол получает ـتْ. Эта ت только указывает род и не является местоимением.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">تَاءُ التَّأْنِيثِ السَّاكِنَةُ</span><span class="rule-term-ru">показатель женского рода в прошедшем</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ذَهَبَتْ آمِنَةُ.</span><span class="rule-example-ru">Амина ушла.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '4', 'rule', 'показатель женского рода в прошедшем. С явным исполнителем женского рода прошедший глагол получает ـتْ. Эта ت только указывает род и не является местоимением.'),
('Мединский курс (Том 2)', '6', 'تَأْنِيثُ الْفِعْلِ مَعَ الْفَاعِلِ (согласование с женским исполнителем)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">تَأْنِيثُ الْفِعْلِ مَعَ الْفَاعِلِ</span><p class="rule-study-text">согласование с женским исполнителем. Если после глагола стоит женщина или женское единственное имя, прошедший глагол получает تَاءُ التَّأْنِيثِ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">تَأْنِيثُ الْفِعْلِ مَعَ الْفَاعِلِ</span><span class="rule-term-ru">согласование с женским исполнителем</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">حَضَرَتِ الطَّالِبَةُ.</span><span class="rule-example-ru">Студентка пришла.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '1', 'rule', 'согласование с женским исполнителем. Если после глагола стоит женщина или женское единственное имя, прошедший глагол получает تَاءُ التَّأْنِيثِ.'),
('Мединский курс (Том 2)', '6', 'ضَمَائِرُ الْغَائِبِ مَفْعُولًا بِهِ (местоимения третьего лица как дополнение)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">ضَمَائِرُ الْغَائِبِ مَفْعُولًا بِهِ</span><p class="rule-study-text">местоимения третьего лица как дополнение. ـهُ، ـهُا، ـهُمَا، ـهُمْ، ـهُنَّ присоединяются непосредственно к глаголу.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">ضَمَائِرُ الْغَائِبِ مَفْعُولًا بِهِ</span><span class="rule-term-ru">местоимения третьего лица как дополнение</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">رَأَيْتُهُمْ.</span><span class="rule-example-ru">Я увидел их.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">سَأَلْتُهَا.</span><span class="rule-example-ru">Я спросил ее.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '2', 'rule', 'местоимения третьего лица как дополнение. ـهُ، ـهُا، ـهُمَا، ـهُمْ، ـهُنَّ присоединяются непосредственно к глаголу.'),
('Мединский курс (Том 2)', '6', 'أَنَّ (союз «что»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَنَّ</span><p class="rule-study-text">союз «что». أَنَّ вводит придаточное и действует как إِنَّ: имя получает винительный падеж, сказуемое — именительный.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَنَّ</span><span class="rule-term-ru">союз «что»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِنَّ</span><span class="rule-term-ru">إِنَّ — «поистине, воистину»; حَرْفُ تَوْكِيدٍ وَنَصْبٍ: усиливает утверждение и ставит своё имя в نَصْب.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите именное предложение: مُبْتَدَأٌ + خَبَرٌ.</li><li>Поставьте после частицы её имя в نَصْب.</li><li>Оставьте её خَبَرٌ в رَفْع и переведите смысл самой частицы.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أَظُنُّ أَنَّ الْجَوَّ جَمِيلٌ.</span><span class="rule-example-ru">Я думаю, что погода хорошая.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Главная ошибка: после إِنَّ писать имя с даммой. Правильно: إِنَّ الطَّالِبَ مُجْتَهِدٌ — الطَّالِبَ в نَصْب, مُجْتَهِدٌ в رَفْع.</div></div>', '3', 'rule', 'союз «что». أَنَّ вводит придаточное и действует как إِنَّ: имя получает винительный падеж, сказуемое — именительный.'),
('Мединский курс (Том 2)', '6', 'مُؤَنَّثُ فَعْلَانَ وَجَمْعُهُ (формы модели فَعْلَان)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مُؤَنَّثُ فَعْلَانَ وَجَمْعُهُ</span><p class="rule-study-text">формы модели فَعْلَان. Состояния на فَعْلَانُ часто имеют женскую форму فَعْلَى и особое ломаное множественное.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مُؤَنَّثُ فَعْلَانَ وَجَمْعُهُ</span><span class="rule-term-ru">формы модели فَعْلَان</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هُوَ عَطْشَانُ وَهِيَ عَطْشَى.</span><span class="rule-example-ru">Он и она испытывают жажду.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هُمْ عِطَاشٌ.</span><span class="rule-example-ru">Они испытывают жажду.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '4', 'rule', 'формы модели فَعْلَان. Состояния на فَعْلَانُ часто имеют женскую форму فَعْلَى и особое ломаное множественное.'),
('Мединский курс (Том 2)', '6', 'أَنْوَاعُ الْإِعْرَابِ فِي الْأَسْمَاءِ (три падежных состояния имен)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَنْوَاعُ الْإِعْرَابِ فِي الْأَسْمَاءِ</span><p class="rule-study-text">три падежных состояния имен. Имя бывает مرفوعًا, منصوبًا или مجرورًا. Основные признаки единственного имени: дамма, фатха и касра.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَنْوَاعُ الْإِعْرَابِ فِي الْأَسْمَاءِ</span><span class="rule-term-ru">три падежных состояния имен</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">جَاءَ طَالِبٌ، رَأَيْتُ طَالِبًا، مَرَرْتُ بِطَالِبٍ.</span><span class="rule-example-ru">Пришел студент; я увидел студента; я прошел мимо студента.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '5', 'rule', 'три падежных состояния имен. Имя бывает مرفوعًا, منصوبًا или مجرورًا. Основные признаки единственного имени: дамма, фатха и касра.'),
('Мединский курс (Том 2)', '6', 'لِمَ وَلِمَهْ وَهَاتِ («почему?» и «дай/принеси»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">لِمَ وَلِمَهْ وَهَاتِ</span><p class="rule-study-text">«почему?» и «дай/принеси». لِمَ образовано из لِ + مَا с удалением алифа; при паузе возможно لِمَهْ. هَاتِ — неизменяемое слово побуждения.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لِمَ وَلِمَهْ وَهَاتِ</span><span class="rule-term-ru">«почему?» и «дай/принеси»</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لِمَ غِبْتَ؟</span><span class="rule-example-ru">Почему ты отсутствовал?</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هَاتِ الْكِتَابَ.</span><span class="rule-example-ru">Дай книгу.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '6', 'rule', '«почему?» и «дай/принеси». لِمَ образовано из لِ + مَا с удалением алифа; при паузе возможно لِمَهْ. هَاتِ — неизменяемое слово побуждения.'),
('Мединский курс (Том 2)', '7', 'تَأْنِيثُ الْفَاعِلِ الْمُفْرَدِ وَالْجَمْعِ (женский исполнитель в единственном и множественном)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">تَأْنِيثُ الْفَاعِلِ الْمُفْرَدِ وَالْجَمْعِ</span><p class="rule-study-text">женский исполнитель в единственном и множественном. С реальным женским единственным исполнителем согласование обязательно. Неодушевленное ломаное множественное обычно согласуется как женское единственное.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">تَأْنِيثُ الْفَاعِلِ الْمُفْرَدِ وَالْجَمْعِ</span><span class="rule-term-ru">женский исполнитель в единственном и множественном</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">حَضَرَتْ فَاطِمَةُ.</span><span class="rule-example-ru">Фатима пришла.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">سَقَطَتِ الْكُتُبُ.</span><span class="rule-example-ru">Книги упали.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '1', 'rule', 'женский исполнитель в единственном и множественном. С реальным женским единственным исполнителем согласование обязательно. Неодушевленное ломаное множественное обычно согласуется как женское единственное.'),
('Мединский курс (Том 2)', '7', 'الْتِقَاءُ السَّاكِنَيْنِ (встреча двух сукунов)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْتِقَاءُ السَّاكِنَيْنِ</span><p class="rule-study-text">встреча двух сукунов. Два сукуна подряд не произносятся. Первый звук получает вспомогательную гласную или изменяется по установленному правилу.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الْتِقَاءُ السَّاكِنَيْنِ</span><span class="rule-term-ru">встреча двух сукунов</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">قَالَتِ الطَّالِبَةُ.</span><span class="rule-example-ru">Студентка сказала.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '2', 'rule', 'встреча двух сукунов. Два сукуна подряд не произносятся. Первый звук получает вспомогательную гласную или изменяется по установленному правилу.'),
('Мединский курс (Том 2)', '7', 'كَانَ وَخَبَرُهَا شِبْهُ جُمْلَةٍ (كَانَ со сказуемым-обстоятельством)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">كَانَ وَخَبَرُهَا شِبْهُ جُمْلَةٍ</span><p class="rule-study-text">كَانَ со сказуемым-обстоятельством. كَانَ переносит состояние в прошлое. Ее имя именительное, сказуемое винительное по позиции; сочетание с предлогом может стоять первым.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">كَانَ وَخَبَرُهَا شِبْهُ جُمْلَةٍ</span><span class="rule-term-ru">كَانَ со сказуемым-обстоятельством</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">كَانَ</span><span class="rule-term-ru">كَانَ — «был/была»; её имя в رَفْع, خَبَرٌ в نَصْب.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите имя этой частицы/глагола.</li><li>Проверьте: имя в رَفْع.</li><li>Проверьте: خَبَرٌ в نَصْب, даже если смысл по-русски похож на обычное сказуемое.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">كَانَ فِي الْفَصْلِ طُلَّابٌ.</span><span class="rule-example-ru">В классе были студенты.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не оставляйте خَبَرٌ لَيْسَ или خَبَرٌ كَانَ в рафʿе: это место требует نَصْب.</div></div>', '3', 'rule', 'كَانَ со сказуемым-обстоятельством. كَانَ переносит состояние в прошлое. Ее имя именительное, сказуемое винительное по позиции; сочетание с предлогом может стоять первым.'),
('Мединский курс (Том 2)', '7', 'ذُو وَذَاتُ نَعْتًا (ذُو и ذَاتُ как определение)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">ذُو وَذَاتُ نَعْتًا</span><p class="rule-study-text">ذُو и ذَاتُ как определение. Как прилагательное ذُو/ذَاتُ согласуется с определяемым именем в роде, числе, определенности и падеже.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">ذُو وَذَاتُ نَعْتًا</span><span class="rule-term-ru">ذُو и ذَاتُ как определение</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число и разряд.</li><li>Проверьте род числительного и род الْمَعْدُودُ.</li><li>Поставьте الْمَعْدُودُ в нужное число и падеж.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">جَاءَ الرَّجُلُ ذُو اللِّحْيَةِ.</span><span class="rule-example-ru">Пришел мужчина с бородой.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя применять одно правило ко всем числам: ٣–١٠, ١١–١٩, десятки, сотни и тысячи ведут себя по-разному.</div></div>', '4', 'rule', 'ذُو и ذَاتُ как определение. Как прилагательное ذُو/ذَاتُ согласуется с определяемым именем в роде, числе, определенности и падеже.'),
('Мединский курс (Том 2)', '8', 'جَدْوَلُ الْفِعْلِ الْمَاضِي (полная таблица прошедшего времени)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">جَدْوَلُ الْفِعْلِ الْمَاضِي</span><p class="rule-study-text">полная таблица прошедшего времени. Спряжение строится от одной основы и набора окончаний. Особо различайте هُمْ ذَهَبُوا и هُنَّ ذَهَبْنَ, أَنْتُمْ ذَهَبْتُمْ и أَنْتُنَّ ذَهَبْتُنَّ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">جَدْوَلُ الْفِعْلِ الْمَاضِي</span><span class="rule-term-ru">полная таблица прошедшего времени</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْفِعْلُ الْمَاضِي</span><span class="rule-term-ru">الْفِعْلُ الْمَاضِي — глагол прошедшего времени.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هُمَا ذَهَبَا وَهُمَا ذَهَبَتَا.</span><span class="rule-example-ru">Они двое ушли: мужская и женская формы.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '1', 'rule', 'полная таблица прошедшего времени. Спряжение строится от одной основы и набора окончаний. Особо различайте هُمْ ذَهَبُوا и هُنَّ ذَهَبْنَ, أَنْتُمْ ذَهَبْتُمْ и أَنْتُنَّ ذَهَبْتُنَّ.'),
('Мединский курс (Том 2)', '8', 'عَلَامَاتُ التَّصْرِيفِ وَالضَّمَائِرُ (показатели формы и местоимения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">عَلَامَاتُ التَّصْرِيفِ وَالضَّمَائِرُ</span><p class="rule-study-text">показатели формы и местоимения. Не каждое окончание является отдельным местоимением: تَاءُ التَّأْنِيثِ лишь указывает женский род, а تَاءُ الْفَاعِلِ сама обозначает исполнителя.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">عَلَامَاتُ التَّصْرِيفِ وَالضَّمَائِرُ</span><span class="rule-term-ru">показатели формы и местоимения</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">كَتَبَتْ فَاطِمَةُ؛ كَتَبْتُ.</span><span class="rule-example-ru">Фатима написала; я написал.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '2', 'rule', 'показатели формы и местоимения. Не каждое окончание является отдельным местоимением: تَاءُ التَّأْنِيثِ лишь указывает женский род, а تَاءُ الْفَاعِلِ сама обозначает исполнителя.'),
('Мединский курс (Том 2)', '8', 'الضَّمِيرُ الْمُسْتَتِرُ وَالْبَارِزُ (скрытое и выраженное местоимение)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الضَّمِيرُ الْمُسْتَتِرُ وَالْبَارِزُ</span><p class="rule-study-text">скрытое и выраженное местоимение. Исполнитель может быть скрыт внутри формы глагола или явно выражен окончанием/отдельным словом.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الضَّمِيرُ الْمُسْتَتِرُ وَالْبَارِزُ</span><span class="rule-term-ru">скрытое и выраженное местоимение</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ذَهَبَ: الْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ هُوَ.</span><span class="rule-example-ru">В «ушел» скрытый исполнитель «он».</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '3', 'rule', 'скрытое и выраженное местоимение. Исполнитель может быть скрыт внутри формы глагола или явно выражен окончанием/отдельным словом.'),
('Мединский курс (Том 2)', '8', 'الضَّمِيرُ الْمُتَّصِلُ وَالْمُنْفَصِلُ (слитное и раздельное местоимение)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الضَّمِيرُ الْمُتَّصِلُ وَالْمُنْفَصِلُ</span><p class="rule-study-text">слитное и раздельное местоимение. Раздельное местоимение пишется самостоятельно, слитное — только вместе с глаголом, именем или предлогом.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الضَّمِيرُ الْمُتَّصِلُ وَالْمُنْفَصِلُ</span><span class="rule-term-ru">слитное и раздельное местоимение</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هُوَ طَالِبٌ؛ كِتَابُهُ جَدِيدٌ.</span><span class="rule-example-ru">Он студент; его книга новая.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '4', 'rule', 'слитное и раздельное местоимение. Раздельное местоимение пишется самостоятельно, слитное — только вместе с глаголом, именем или предлогом.'),
('Мединский курс (Том 2)', '9', 'فِعْلُ التَّعَجُّبِ (форма восклицания مَا أَفْعَلَهُ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">فِعْلُ التَّعَجُّبِ</span><p class="rule-study-text">форма восклицания مَا أَفْعَلَهُ. Модель مَا أَفْعَلَ выражает сильное впечатление. Предмет впечатления ставится как дополнение.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">فِعْلُ التَّعَجُّبِ</span><span class="rule-term-ru">форма восклицания مَا أَفْعَلَهُ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مَا أَجْمَلَ السَّمَاءَ!</span><span class="rule-example-ru">Как прекрасно небо!</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '1', 'rule', 'форма восклицания مَا أَفْعَلَهُ. Модель مَا أَفْعَلَ выражает сильное впечатление. Предмет впечатления ставится как дополнение.'),
('Мединский курс (Том 2)', '9', 'الْمُنَادَى الْمُفْرَدُ وَالْمُضَافُ (обращение: одиночное и в идафе)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمُنَادَى الْمُفْرَدُ وَالْمُضَافُ</span><p class="rule-study-text">обращение: одиночное и в идафе. Определенное одиночное обращение строится на дамме, а обращение в идафе стоит в винительном.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْمُنَادَى الْمُفْرَدُ وَالْمُضَافُ</span><span class="rule-term-ru">обращение: одиночное и в идафе</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите مَنْعُوتٌ — определяемое слово.</li><li>Поставьте после него نَعْتٌ.</li><li>Согласуйте نَعْتٌ в падеже, определённости, роде и числе.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">يَا مُحَمَّدُ!</span><span class="rule-example-ru">О Мухаммад!</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">يَا عَبْدَ اللهِ!</span><span class="rule-example-ru">О раб Аллаха!</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя переводить прилагательное отдельно от определяемого слова: его окончание зависит от مَنْعُوت.</div></div>', '2', 'rule', 'обращение: одиночное и в идафе. Определенное одиночное обращение строится на дамме, а обращение в идафе стоит в винительном.'),
('Мединский курс (Том 2)', '9', 'جَمْعُ الْمُؤَنَّثِ السَّالِمُ (правильное женское множественное)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">جَمْعُ الْمُؤَنَّثِ السَّالِمُ</span><p class="rule-study-text">правильное женское множественное. В именительном окончание ـَاتُ, в винительном и родительном — ـَاتِ. В винительном используется касра.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">جَمْعُ الْمُؤَنَّثِ السَّالِمُ</span><span class="rule-term-ru">правильное женское множественное</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">حَضَرَتِ الطَّالِبَاتُ.</span><span class="rule-example-ru">Студентки пришли.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">رَأَيْتُ الطَّالِبَاتِ.</span><span class="rule-example-ru">Я увидел студенток.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '3', 'rule', 'правильное женское множественное. В именительном окончание ـَاتُ, в винительном и родительном — ـَاتِ. В винительном используется касра.'),
('Мединский курс (Том 2)', '9', 'هَمْزَةُ الِاسْتِفْهَامِ مَعَ ال (вопросительная أَ перед артиклем)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">هَمْزَةُ الِاسْتِفْهَامِ مَعَ ال</span><p class="rule-study-text">вопросительная أَ перед артиклем. При соединении أَ с ال две хамзы могут перейти в долгий آ для ясного произношения.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">هَمْزَةُ الِاسْتِفْهَامِ مَعَ ال</span><span class="rule-term-ru">вопросительная أَ перед артиклем</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">آلطَّالِبُ جَدِيدٌ؟</span><span class="rule-example-ru">Этот студент новый?</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '4', 'rule', 'вопросительная أَ перед артиклем. При соединении أَ с ال две хамзы могут перейти в долгий آ для ясного произношения.'),
('Мединский курс (Том 2)', '9', 'ضَمَائِرُ النَّصْبِ وَنُونُ الْوِقَايَةِ (объектные местоимения и защитная ن)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">ضَمَائِرُ النَّصْبِ وَنُونُ الْوِقَايَةِ</span><p class="rule-study-text">объектные местоимения и защитная ن. Перед ي говорящего у глагола появляется نُونُ الْوِقَايَةِ: أَكْرَمَنِي. Она защищает основу от касры.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">ضَمَائِرُ النَّصْبِ وَنُونُ الْوِقَايَةِ</span><span class="rule-term-ru">объектные местоимения и защитная ن</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">سَأَلَنِي الْمُدَرِّسُ.</span><span class="rule-example-ru">Учитель спросил меня.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '5', 'rule', 'объектные местоимения и защитная ن. Перед ي говорящего у глагола появляется نُونُ الْوِقَايَةِ: أَكْرَمَنِي. Она защищает основу от касры.'),
('Мединский курс (Том 2)', '9', 'حَذْفُ أَلِفِ مَا الِاسْتِفْهَامِيَّةِ (удаление алифа в вопросительном مَا)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">حَذْفُ أَلِفِ مَا الِاسْتِفْهَامِيَّةِ</span><p class="rule-study-text">удаление алифа в вопросительном مَا. После предлога алиф вопросительного مَا удаляется: بِمَ، لِمَ، مِمَّ، عَمَّ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">حَذْفُ أَلِفِ مَا الِاسْتِفْهَامِيَّةِ</span><span class="rule-term-ru">удаление алифа в вопросительном مَا</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">بِمَ كَتَبْتَ؟</span><span class="rule-example-ru">Чем ты написал?</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">عَمَّ تَسْأَلُ؟</span><span class="rule-example-ru">О чем ты спрашиваешь?</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '6', 'rule', 'удаление алифа в вопросительном مَا. После предлога алиф вопросительного مَا удаляется: بِمَ، لِمَ، مِمَّ، عَمَّ.'),
('Мединский курс (Том 2)', '9', 'الْأَسْمَاءُ الْمَوْصُولَةُ (относительные местоимения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْأَسْمَاءُ الْمَوْصُولَةُ</span><p class="rule-study-text">относительные местоимения. Форма выбирается по роду и числу: الَّذِي، الَّتِي، اللَّذَانِ، اللَّتَانِ، الَّذِينَ، اللَّاتِي. После нее идет поясняющее предложение.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْأَسْمَاءُ الْمَوْصُولَةُ</span><span class="rule-term-ru">относительные местоимения</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число и разряд.</li><li>Проверьте род числительного и род الْمَعْدُودُ.</li><li>Поставьте الْمَعْدُودُ в нужное число и падеж.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">جَاءَ الطُّلَّابُ الَّذِينَ نَجَحُوا.</span><span class="rule-example-ru">Пришли студенты, которые сдали.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя применять одно правило ко всем числам: ٣–١٠, ١١–١٩, десятки, сотни и тысячи ведут себя по-разному.</div></div>', '7', 'rule', 'относительные местоимения. Форма выбирается по роду и числу: الَّذِي، الَّتِي، اللَّذَانِ، اللَّتَانِ، الَّذِينَ، اللَّاتِي. После нее идет поясняющее предложение.'),
('Мединский курс (Том 2)', '10', 'الْفِعْلُ الْمَاضِي وَالْمُضَارِعُ (прошедший и настоящее-будущее время)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْفِعْلُ الْمَاضِي وَالْمُضَارِعُ</span><p class="rule-study-text">прошедший и настоящее-будущее время. Прошедшее сообщает о завершенном действии. الْمُضَارِعُ сообщает о настоящем или будущем и начинается одной из букв أ، ن، ي، ت.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْفِعْلُ الْمَاضِي وَالْمُضَارِعُ</span><span class="rule-term-ru">прошедший и настоящее-будущее время</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْفِعْلُ الْمَاضِي</span><span class="rule-term-ru">الْفِعْلُ الْمَاضِي — глагол прошедшего времени.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">كَتَبَ يَكْتُبُ.</span><span class="rule-example-ru">Он написал; он пишет.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '1', 'rule', 'прошедший и настоящее-будущее время. Прошедшее сообщает о завершенном действии. الْمُضَارِعُ сообщает о настоящем или будущем и начинается одной из букв أ، ن، ي، ت.'),
('Мединский курс (Том 2)', '10', 'إِعْرَابُ الْفِعْلِ الْمُضَارِعِ (изменение окончания الْمُضَارِعُ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">إِعْرَابُ الْفِعْلِ الْمُضَارِعِ</span><p class="rule-study-text">изменение окончания الْمُضَارِعُ. Настоящий глагол бывает именительным, винительным или усеченным; частица перед ним определяет окончание.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِعْرَابُ الْفِعْلِ الْمُضَارِعِ</span><span class="rule-term-ru">изменение окончания الْمُضَارِعُ</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْفِعْلُ الْمُضَارِعُ</span><span class="rule-term-ru">الْفِعْلُ الْمُضَارِعُ — глагол настоящего/будущего времени.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">يَكْتُبُ، لَنْ يَكْتُبَ، لَمْ يَكْتُبْ.</span><span class="rule-example-ru">Пишет; не будет писать; не писал.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '2', 'rule', 'изменение окончания الْمُضَارِعُ. Настоящий глагол бывает именительным, винительным или усеченным; частица перед ним определяет окончание.'),
('Мединский курс (Том 2)', '10', 'الْأَعْدَادُ الْمَعْطُوفَةُ ٢١–٩٩ (составные числа 21–99)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْأَعْدَادُ الْمَعْطُوفَةُ ٢١–٩٩</span><p class="rule-study-text">составные числа 21–99. Единицы соединяются с десятками через وَ. Род определяется единицей, десятки не меняются по роду; считаемое — единственное винительное.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْأَعْدَادُ الْمَعْطُوفَةُ ٢١–٩٩</span><span class="rule-term-ru">составные числа 21–99</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число и разряд.</li><li>Проверьте род числительного и род الْمَعْدُودُ.</li><li>Поставьте الْمَعْدُودُ в нужное число и падеж.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">وَاحِدٌ وَعِشْرُونَ طَالِبًا.</span><span class="rule-example-ru">Двадцать один студент.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">إِحْدَى وَعِشْرُونَ طَالِبَةً.</span><span class="rule-example-ru">Двадцать одна студентка.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя применять одно правило ко всем числам: ٣–١٠, ١١–١٩, десятки, сотни и тысячи ведут себя по-разному.</div></div>', '3', 'rule', 'составные числа 21–99. Единицы соединяются с десятками через وَ. Род определяется единицей, десятки не меняются по роду; считаемое — единственное винительное.'),
('Мединский курс (Том 2)', '10', 'أَبْوَابُ الْمَاضِي وَالْمُضَارِعِ (огласовочные модели I породы)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَبْوَابُ الْمَاضِي وَالْمُضَارِعِ</span><p class="rule-study-text">огласовочные модели I породы. Гласная середины الْمُضَارِعُ словарная: فَعَلَ يَفْعُلُ, فَعَلَ يَفْعِلُ, فَعَلَ يَفْعَلُ и другие модели. Ее нужно запоминать с глаголом.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَبْوَابُ الْمَاضِي وَالْمُضَارِعِ</span><span class="rule-term-ru">огласовочные модели I породы</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">كَتَبَ يَكْتُبُ؛ جَلَسَ يَجْلِسُ؛ فَتَحَ يَفْتَحُ.</span><span class="rule-example-ru">Писать; сидеть; открывать.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '4', 'rule', 'огласовочные модели I породы. Гласная середины الْمُضَارِعُ словарная: فَعَلَ يَفْعُلُ, فَعَلَ يَفْعِلُ, فَعَلَ يَفْعَلُ и другие модели. Ее нужно запоминать с глаголом.'),
('Мединский курс (Том 2)', '11', 'إِسْنَادُ الْمُضَارِعِ إِلَى الضَّمَائِرِ (спряжение الْمُضَارِعُ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">إِسْنَادُ الْمُضَارِعِ إِلَى الضَّمَائِرِ</span><p class="rule-study-text">спряжение الْمُضَارِعُ. Начальная буква и окончание вместе показывают лицо: أَكْتُبُ، نَكْتُبُ، تَكْتُبُ، يَكْتُبُ. Двойственное и множественное получают ـَانِ، ـُونَ، ـِينَ، ـْنَ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِسْنَادُ الْمُضَارِعِ إِلَى الضَّمَائِرِ</span><span class="rule-term-ru">спряжение الْمُضَارِعُ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هُمْ يَكْتُبُونَ وَأَنْتِ تَكْتُبِينَ.</span><span class="rule-example-ru">Они пишут, и ты, женщина, пишешь.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '1', 'rule', 'спряжение الْمُضَارِعُ. Начальная буква и окончание вместе показывают лицо: أَكْتُبُ، نَكْتُبُ، تَكْتُبُ، يَكْتُبُ. Двойственное и множественное получают ـَانِ، ـُونَ، ـِينَ، ـْنَ.'),
('Мединский курс (Том 2)', '11', 'عَلَامَاتُ رَفْعِ الْمُضَارِعِ (признаки именительного состояния)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">عَلَامَاتُ رَفْعِ الْمُضَارِعِ</span><p class="rule-study-text">признаки именительного состояния. Обычный الْمُضَارِعُ имеет дамму. У пяти глагольных форм признак именительного состояния — сохранение ن.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">عَلَامَاتُ رَفْعِ الْمُضَارِعِ</span><span class="rule-term-ru">признаки именительного состояния</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هُوَ يَكْتُبُ؛ هُمْ يَكْتُبُونَ.</span><span class="rule-example-ru">Он пишет; они пишут.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '2', 'rule', 'признаки именительного состояния. Обычный الْمُضَارِعُ имеет дамму. У пяти глагольных форм признак именительного состояния — сохранение ن.'),
('Мединский курс (Том 2)', '11', 'مَا وَلَا النَّافِيَتَانِ وَسِينُ الِاسْتِقْبَالِ (отрицание настоящего и будущее с سَـ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مَا وَلَا النَّافِيَتَانِ وَسِينُ الِاسْتِقْبَالِ</span><p class="rule-study-text">отрицание настоящего и будущее с سَـ. مَا и لَا отрицают настоящее и не меняют окончание. سَـ пишется слитно с الْمُضَارِعُ и переносит действие в будущее.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا وَلَا النَّافِيَتَانِ وَسِينُ الِاسْتِقْبَالِ</span><span class="rule-term-ru">отрицание настоящего и будущее с سَـ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لَا أَفْهَمُ هَذَا.</span><span class="rule-example-ru">Я не понимаю это.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">سَأَذْهَبُ غَدًا.</span><span class="rule-example-ru">Я пойду завтра.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '3', 'rule', 'отрицание настоящего и будущее с سَـ. مَا и لَا отрицают настоящее и не меняют окончание. سَـ пишется слитно с الْمُضَارِعُ и переносит действие в будущее.'),
('Мединский курс (Том 2)', '11', 'مَصْدَرُ فُعُولٍ (масдар модели فُعُول)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مَصْدَرُ فُعُولٍ</span><p class="rule-study-text">масдар модели فُعُول. Масдар на فُعُول часто образуется от глаголов движения и состояния, но масдары I породы во многом словарные.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَصْدَرُ فُعُولٍ</span><span class="rule-term-ru">масдар модели فُعُول</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">دَخَلَ دُخُولًا؛ خَرَجَ خُرُوجًا.</span><span class="rule-example-ru">Вошел — вход; вышел — выход.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '4', 'rule', 'масдар модели فُعُول. Масдар на فُعُول часто образуется от глаголов движения и состояния, но масдары I породы во многом словарные.'),
('Мединский курс (Том 2)', '11', 'أَمَّا ... فَـ (оборот «что касается..., то...»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَمَّا ... فَـ</span><p class="rule-study-text">оборот «что касается..., то...». После أَمَّا называется тема, а ответ обычно начинается с فَـ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَمَّا ... فَـ</span><span class="rule-term-ru">оборот «что касается..., то...»</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أَمَّا خَالِدٌ فَهُوَ طَبِيبٌ.</span><span class="rule-example-ru">Что касается Халида, то он врач.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '5', 'rule', 'оборот «что касается..., то...». После أَمَّا называется тема, а ответ обычно начинается с فَـ.'),
('Мединский курс (Том 2)', '11', 'أَخِي وَأَخٌ لِي («мой брат» и «один из моих братьев»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَخِي وَأَخٌ لِي</span><p class="rule-study-text">«мой брат» и «один из моих братьев». أَخِي определяет конкретного брата. أَخٌ لِي сообщает об одном брате без уточнения.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَخِي وَأَخٌ لِي</span><span class="rule-term-ru">«мой брат» и «один из моих братьев»</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите مَنْعُوتٌ — определяемое слово.</li><li>Поставьте после него نَعْتٌ.</li><li>Согласуйте نَعْتٌ в падеже, определённости, роде и числе.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا أَخِي؛ هَذَا أَخٌ لِي.</span><span class="rule-example-ru">Это мой брат; это один из моих братьев.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя переводить прилагательное отдельно от определяемого слова: его окончание зависит от مَنْعُوت.</div></div>', '6', 'rule', '«мой брат» и «один из моих братьев». أَخِي определяет конкретного брата. أَخٌ لِي сообщает об одном брате без уточнения.'),
('Мединский курс (Том 2)', '12', 'وَاوُ الْجَمَاعَةِ وَيَاءُ الْمُخَاطَبَةِ وَنُونُ النِّسْوَةِ (окончания الْمُضَارِعُ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">وَاوُ الْجَمَاعَةِ وَيَاءُ الْمُخَاطَبَةِ وَنُونُ النِّسْوَةِ</span><p class="rule-study-text">окончания الْمُضَارِعُ. Различайте يَكْتُبُونَ, تَكْتُبِينَ и يَكْتُبْنَ. У نُونٌ النِّسْوَةِ глагол неизменяем и перед ن стоит сукун.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَاوُ الْجَمَاعَةِ وَيَاءُ الْمُخَاطَبَةِ وَنُونُ النِّسْوَةِ</span><span class="rule-term-ru">окончания الْمُضَارِعُ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هُنَّ يَكْتُبْنَ وَأَنْتِ تَكْتُبِينَ.</span><span class="rule-example-ru">Они, женщины, пишут, и ты пишешь.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '1', 'rule', 'окончания الْمُضَارِعُ. Различайте يَكْتُبُونَ, تَكْتُبِينَ и يَكْتُبْنَ. У نُونٌ النِّسْوَةِ глагол неизменяем и перед ن стоит сукун.'),
('Мединский курс (Том 2)', '12', 'ظَرْفُ الزَّمَانِ (обстоятельство времени)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">ظَرْفُ الزَّمَانِ</span><p class="rule-study-text">обстоятельство времени. Слова времени отвечают на «когда?» и часто стоят в винительном падеже: يَوْمًا، لَيْلًا، صَبَاحًا.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">ظَرْفُ الزَّمَانِ</span><span class="rule-term-ru">обстоятельство времени</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">سَأَزُورُكَ مَسَاءً.</span><span class="rule-example-ru">Я навещу тебя вечером.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '2', 'rule', 'обстоятельство времени. Слова времени отвечают на «когда?» и часто стоят в винительном падеже: يَوْمًا، لَيْلًا، صَبَاحًا.'),
('Мединский курс (Том 2)', '12', 'إِنَّ بَعْدَ الْقَوْلِ (إِنَّ после глагола речи)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">إِنَّ بَعْدَ الْقَوْلِ</span><p class="rule-study-text">إِنَّ после глагола речи. После самостоятельной цитаты с قَالَ обычно употребляется إِنَّ с касрой хамзы.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِنَّ بَعْدَ الْقَوْلِ</span><span class="rule-term-ru">إِنَّ после глагола речи</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِنَّ</span><span class="rule-term-ru">إِنَّ — «поистине, воистину»; حَرْفُ تَوْكِيدٍ وَنَصْبٍ: усиливает утверждение и ставит своё имя в نَصْب.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите именное предложение: مُبْتَدَأٌ + خَبَرٌ.</li><li>Поставьте после частицы её имя в نَصْب.</li><li>Оставьте её خَبَرٌ в رَفْع и переведите смысл самой частицы.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">قَالَ الْمُدَرِّسُ: إِنَّ الِامْتِحَانَ غَدًا.</span><span class="rule-example-ru">Учитель сказал: «Экзамен завтра».</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Главная ошибка: после إِنَّ писать имя с даммой. Правильно: إِنَّ الطَّالِبَ مُجْتَهِدٌ — الطَّالِبَ в نَصْب, مُجْتَهِدٌ в رَفْع.</div></div>', '3', 'rule', 'إِنَّ после глагола речи. После самостоятельной цитаты с قَالَ обычно употребляется إِنَّ с касрой хамзы.'),
('Мединский курс (Том 2)', '13', 'إِنَّ وَأَنَّ (различие إِنَّ и أَنَّ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">إِنَّ وَأَنَّ</span><p class="rule-study-text">различие إِنَّ и أَنَّ. إِنَّ начинает самостоятельное высказывание или цитату. أَنَّ входит внутрь более крупной конструкции и вместе со своим предложением заменяет имя.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِنَّ وَأَنَّ</span><span class="rule-term-ru">различие إِنَّ и أَنَّ</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِنَّ</span><span class="rule-term-ru">إِنَّ — «поистине, воистину»; حَرْفُ تَوْكِيدٍ وَنَصْبٍ: усиливает утверждение и ставит своё имя в نَصْب.</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَنَّ</span><span class="rule-term-ru">أَنَّ — «что»; вводит придаточное сообщение и действует как إِنَّ.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите именное предложение: مُبْتَدَأٌ + خَبَرٌ.</li><li>Поставьте после частицы её имя в نَصْب.</li><li>Оставьте её خَبَرٌ в رَفْع и переведите смысл самой частицы.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">عَلِمْتُ أَنَّ الدَّرْسَ سَهْلٌ.</span><span class="rule-example-ru">Я узнал, что урок легкий.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">قَالَ: إِنَّ الدَّرْسَ سَهْلٌ.</span><span class="rule-example-ru">Он сказал: «Урок легкий».</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Главная ошибка: после إِنَّ писать имя с даммой. Правильно: إِنَّ الطَّالِبَ مُجْتَهِدٌ — الطَّالِبَ в نَصْب, مُجْتَهِدٌ в رَفْع.</div></div>', '1', 'rule', 'различие إِنَّ и أَنَّ. إِنَّ начинает самостоятельное высказывание или цитату. أَنَّ входит внутрь более крупной конструкции и вместе со своим предложением заменяет имя.'),
('Мединский курс (Том 2)', '13', 'مُرَاجَعَةُ تَصْرِيفِ الْمُضَارِعِ (повторение спряжения الْمُضَارِعُ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مُرَاجَعَةُ تَصْرِيفِ الْمُضَارِعِ</span><p class="rule-study-text">повторение спряжения الْمُضَارِعُ. Проверяйте форму в три шага: начальная буква лица, основа глагола, окончание числа и рода.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مُرَاجَعَةُ تَصْرِيفِ الْمُضَارِعِ</span><span class="rule-term-ru">повторение спряжения الْمُضَارِعُ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число и разряд.</li><li>Проверьте род числительного и род الْمَعْدُودُ.</li><li>Поставьте الْمَعْدُودُ в нужное число и падеж.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أَنَا أَدْرُسُ، نَحْنُ نَدْرُسُ، هُمْ يَدْرُسُونَ.</span><span class="rule-example-ru">Я учусь, мы учимся, они учатся.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя применять одно правило ко всем числам: ٣–١٠, ١١–١٩, десятки, сотни и тысячи ведут себя по-разному.</div></div>', '2', 'rule', 'повторение спряжения الْمُضَارِعُ. Проверяйте форму в три шага: начальная буква лица, основа глагола, окончание числа и рода.'),
('Мединский курс (Том 2)', '14', 'فِعْلُ الْأَمْرِ (повелительное наклонение)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">فِعْلُ الْأَمْرِ</span><p class="rule-study-text">повелительное наклонение. Повелительная форма строится для второго лица от усеченной формы الْمُضَارِعُ: убирается تَـ, а при невозможности начать с сукуна добавляется هَمْزَةُ الْوَصْلِ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">فِعْلُ الْأَمْرِ</span><span class="rule-term-ru">повелительное наклонение</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">تَكْتُبُ ← لَمْ تَكْتُبْ ← اُكْتُبْ.</span><span class="rule-example-ru">Ты пишешь → ты не писал → пиши.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '1', 'rule', 'повелительное наклонение. Повелительная форма строится для второго лица от усеченной формы الْمُضَارِعُ: убирается تَـ, а при невозможности начать с сукуна добавляется هَمْزَةُ الْوَصْلِ.'),
('Мединский курс (Том 2)', '14', 'هَمْزَةُ الْوَصْلِ فِي الْأَمْرِ الثُّلَاثِيِّ (соединительная хамза)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">هَمْزَةُ الْوَصْلِ فِي الْأَمْرِ الثُّلَاثِيِّ</span><p class="rule-study-text">соединительная хамза. Огласовка начальной хамзы зависит от гласной середины الْمُضَارِعُ: при дамме обычно اُ, иначе اِ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">هَمْزَةُ الْوَصْلِ فِي الْأَمْرِ الثُّلَاثِيِّ</span><span class="rule-term-ru">соединительная хамза</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">يَكْتُبُ: اُكْتُبْ؛ يَجْلِسُ: اِجْلِسْ.</span><span class="rule-example-ru">Пиши; сядь.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '2', 'rule', 'соединительная хамза. Огласовка начальной хамзы зависит от гласной середины الْمُضَارِعُ: при дамме обычно اُ, иначе اِ.'),
('Мединский курс (Том 2)', '14', 'تَصْرِيفُ الْأَمْرِ وَبِنَاؤُهُ (пять форм повелительного)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">تَصْرِيفُ الْأَمْرِ وَبِنَاؤُهُ</span><p class="rule-study-text">пять форм повелительного. Формы второго лица: اُكْتُبْ، اُكْتُبَا، اُكْتُبُوا، اُكْتُبِي، اُكْتُبْنَ. Они строятся на сукуне, удалении ن или слабой буквы.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">تَصْرِيفُ الْأَمْرِ وَبِنَاؤُهُ</span><span class="rule-term-ru">пять форм повелительного</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">اُدْخُلُوا الْفَصْلَ.</span><span class="rule-example-ru">Войдите в класс.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">اُكْتُبْنَ الدَّرْسَ.</span><span class="rule-example-ru">Пишите урок, женщины.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '3', 'rule', 'пять форм повелительного. Формы второго лица: اُكْتُبْ، اُكْتُبَا، اُكْتُبُوا، اُكْتُبِي، اُكْتُبْنَ. Они строятся на сукуне, удалении ن или слабой буквы.'),
('Мединский курс (Том 2)', '15', 'لَا النَّاهِيَةُ (запретительная لَا)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">لَا النَّاهِيَةُ</span><p class="rule-study-text">запретительная لَا. لَا النَّاهِيَةُ означает «не делай» и переводит الْمُضَارِعُ в усеченное состояние.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا النَّاهِيَةُ</span><span class="rule-term-ru">запретительная لَا</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لَا تَذْهَبْ.</span><span class="rule-example-ru">Не уходи.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لَا تَكْتُبُوا.</span><span class="rule-example-ru">Не пишите.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '1', 'rule', 'запретительная لَا. لَا النَّاهِيَةُ означает «не делай» и переводит الْمُضَارِعُ в усеченное состояние.'),
('Мединский курс (Том 2)', '15', 'لَا النَّافِيَةُ وَلَا النَّاهِيَةُ (отрицательная и запретительная لَا)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">لَا النَّافِيَةُ وَلَا النَّاهِيَةُ</span><p class="rule-study-text">отрицательная и запретительная لَا. Отрицательная لَا сообщает факт и оставляет глагол именительным; запретительная обращена к собеседнику и усекает глагол.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا النَّافِيَةُ وَلَا النَّاهِيَةُ</span><span class="rule-term-ru">отрицательная и запретительная لَا</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لَا يَذْهَبُ حَامِدٌ؛ لَا تَذْهَبْ يَا حَامِدُ.</span><span class="rule-example-ru">Хамид не идет; не уходи, Хамид.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '2', 'rule', 'отрицательная и запретительная لَا. Отрицательная لَا сообщает факт и оставляет глагол именительным; запретительная обращена к собеседнику и усекает глагол.'),
('Мединский курс (Том 2)', '15', 'كَادَ («едва не, почти»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">كَادَ</span><p class="rule-study-text">«едва не, почти». كَادَ — نَاقِصٌный глагол. Его имя именительное, а сказуемое обычно выражено الْمُضَارِعُ без أَنْ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">كَادَ</span><span class="rule-term-ru">«едва не, почти»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَنَّ</span><span class="rule-term-ru">أَنَّ — «что»; вводит придаточное сообщение и действует как إِنَّ.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">كَادَ الطِّفْلُ يَسْقُطُ.</span><span class="rule-example-ru">Ребенок едва не упал.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '3', 'rule', '«едва не, почти». كَادَ — نَاقِصٌный глагол. Его имя именительное, а сказуемое обычно выражено الْمُضَارِعُ без أَنْ.'),
('Мединский курс (Том 2)', '15', 'مُرَاجَعَةُ التَّعَجُّبِ (повторение восклицательной модели)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مُرَاجَعَةُ التَّعَجُّبِ</span><p class="rule-study-text">повторение восклицательной модели. В модели مَا أَفْعَلَ объект впечатления стоит в винительном.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مُرَاجَعَةُ التَّعَجُّبِ</span><span class="rule-term-ru">повторение восклицательной модели</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مَا أَحْسَنَ هَذَا الْكِتَابَ!</span><span class="rule-example-ru">Как хороша эта книга!</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '4', 'rule', 'повторение восклицательной модели. В модели مَا أَفْعَلَ объект впечатления стоит в винительном.'),
('Мединский курс (Том 2)', '16', 'إِسْنَادُ يُرِيدُ وَالْمَصْدَرُ الْمُؤَوَّلُ (спряжение «хотеть» и أَنْ + глагол)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">إِسْنَادُ يُرِيدُ وَالْمَصْدَرُ الْمُؤَوَّلُ</span><p class="rule-study-text">спряжение «хотеть» и أَنْ + глагол. У أَرَادَ الْمُضَارِعُ имеет основу رِيد: أُرِيدُ، نُرِيدُ، تُرِيدُ، يُرِيدُ. أَنْ + الْمُضَارِعُ является смысловым эквивалентом масдара.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِسْنَادُ يُرِيدُ وَالْمَصْدَرُ الْمُؤَوَّلُ</span><span class="rule-term-ru">спряжение «хотеть» и أَنْ + глагол</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَنَّ</span><span class="rule-term-ru">أَنَّ — «что»; вводит придаточное сообщение и действует как إِنَّ.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أُرِيدُ أَنْ أَتَعَلَّمَ = أُرِيدُ التَّعَلُّمَ.</span><span class="rule-example-ru">Я хочу учиться = я хочу обучения.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '1', 'rule', 'спряжение «хотеть» и أَنْ + глагол. У أَرَادَ الْمُضَارِعُ имеет основу رِيد: أُرِيدُ، نُرِيدُ، تُرِيدُ، يُرِيدُ. أَنْ + الْمُضَارِعُ является смысловым эквивалентом масдара.'),
('Мединский курс (Том 2)', '16', 'مَا الْمَوْصُولَةُ (относительное مَا «то, что»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مَا الْمَوْصُولَةُ</span><p class="rule-study-text">относительное مَا «то, что». مَا может означать «то, что» и связывать главное предложение с поясняющим.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا الْمَوْصُولَةُ</span><span class="rule-term-ru">относительное مَا «то, что»</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أَفْهَمُ مَا تَقُولُ.</span><span class="rule-example-ru">Я понимаю то, что ты говоришь.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '2', 'rule', 'относительное مَا «то, что». مَا может означать «то, что» и связывать главное предложение с поясняющим.'),
('Мединский курс (Том 2)', '16', 'أَلْوَانُ أَفْعَلَ وَفَعْلَاءُ (цвета мужского и женского рода)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَلْوَانُ أَفْعَلَ وَفَعْلَاءُ</span><p class="rule-study-text">цвета мужского и женского рода. Цвета часто имеют мужскую модель أَفْعَلُ и женскую فَعْلَاءُ; такие слова обычно مَمْنُوعٌ مِنْ الصَّرْفِ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَلْوَانُ أَفْعَلَ وَفَعْلَاءُ</span><span class="rule-term-ru">цвета мужского и женского рода</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">قَمِيصٌ أَبْيَضُ وَسَيَّارَةٌ بَيْضَاءُ.</span><span class="rule-example-ru">Белая рубашка и белый автомобиль.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '3', 'rule', 'цвета мужского и женского рода. Цвета часто имеют мужскую модель أَفْعَلُ и женскую فَعْلَاءُ; такие слова обычно مَمْنُوعٌ مِنْ الصَّرْفِ.'),
('Мединский курс (Том 2)', '16', 'الْعَلَمُ الْمَعْدُولُ وَعُمَرُ وَعَمْرٌو (особые собственные имена)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْعَلَمُ الْمَعْدُولُ وَعُمَرُ وَعَمْرٌو</span><p class="rule-study-text">особые собственные имена. Некоторые имена, включая عُمَرُ, не получают танвин и имеют фатху в родительном без ال/идафы. В عَمْرٌو буква و пишется для отличия, но обычно не произносится.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْعَلَمُ الْمَعْدُولُ وَعُمَرُ وَعَمْرٌو</span><span class="rule-term-ru">особые собственные имена</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">سَلَّمْتُ عَلَى عُمَرَ؛ جَاءَ عَمْرٌو.</span><span class="rule-example-ru">Я поприветствовал Умара; Амр пришел.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '4', 'rule', 'особые собственные имена. Некоторые имена, включая عُمَرُ, не получают танвин и имеют фатху в родительном без ال/идафы. В عَمْرٌو буква و пишется для отличия, но обычно не произносится.'),
('Мединский курс (Том 2)', '16', 'آخَرُ وَأُخْرَى وَغَيْرُ («другой» и «иной, кроме»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">آخَرُ وَأُخْرَى وَغَيْرُ</span><p class="rule-study-text">«другой» и «иной, кроме». آخَرُ/أُخْرَى согласуется как прилагательное. غَيْرُ обычно входит в идафу и получает падеж по своей роли.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">آخَرُ وَأُخْرَى وَغَيْرُ</span><span class="rule-term-ru">«другой» и «иной, кроме»</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите مَنْعُوتٌ — определяемое слово.</li><li>Поставьте после него نَعْتٌ.</li><li>Согласуйте نَعْتٌ в падеже, определённости, роде и числе.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أُرِيدُ كِتَابًا آخَرَ.</span><span class="rule-example-ru">Я хочу другую книгу.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">جَاءَ غَيْرُ خَالِدٍ.</span><span class="rule-example-ru">Пришел не Халид.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя переводить прилагательное отдельно от определяемого слова: его окончание зависит от مَنْعُوت.</div></div>', '5', 'rule', '«другой» и «иной, кроме». آخَرُ/أُخْرَى согласуется как прилагательное. غَيْرُ обычно входит в идафу и получает падеж по своей роли.'),
('Мединский курс (Том 2)', '16', 'إِعْرَابُ ذُو (склонение ذُو)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">إِعْرَابُ ذُو</span><p class="rule-study-text">склонение ذُو. Как одно из пяти имен ذُو меняется буквами: ذُو в именительном, ذَا в винительном, ذِي в родительном.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">إِعْرَابُ ذُو</span><span class="rule-term-ru">склонение ذُو</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите два связанных имени.</li><li>Первое — مُضَافٌ, второе — مُضَافٌ إِلَيْهِ.</li><li>У второго члена всегда جَرّ, а первый не принимает танвин.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">رَأَيْتُ رَجُلًا ذَا عِلْمٍ.</span><span class="rule-example-ru">Я увидел знающего человека.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Первый член идафы не получает одновременно танвин и связь принадлежности.</div></div>', '6', 'rule', 'склонение ذُو. Как одно из пяти имен ذُو меняется буквами: ذُو в именительном, ذَا в винительном, ذِي в родительном.'),
('Мединский курс (Том 2)', '17', 'نَوَاصِبُ الْمُضَارِعِ (частицы винительного состояния)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">نَوَاصِبُ الْمُضَارِعِ</span><p class="rule-study-text">частицы винительного состояния. أَنْ، لَنْ и لَامُ التَّعْلِيلِ ставят الْمُضَارِعُ в винительное состояние. У обычной формы появляется фатха, у пяти глаголов удаляется ن.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">نَوَاصِبُ الْمُضَارِعِ</span><span class="rule-term-ru">частицы винительного состояния</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَنَّ</span><span class="rule-term-ru">أَنَّ — «что»; вводит придаточное сообщение и действует как إِنَّ.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أُرِيدُ أَنْ أَذْهَبَ؛ لَنْ أَتَأَخَّرَ.</span><span class="rule-example-ru">Я хочу пойти; я не опоздаю.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '1', 'rule', 'частицы винительного состояния. أَنْ، لَنْ и لَامُ التَّعْلِيلِ ставят الْمُضَارِعُ в винительное состояние. У обычной формы появляется фатха, у пяти глаголов удаляется ن.'),
('Мединский курс (Том 2)', '17', 'أَنْ وَلَنْ وَلَامُ التَّعْلِيلِ («чтобы», «не будет» и لَامٌ цели)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَنْ وَلَنْ وَلَامُ التَّعْلِيلِ</span><p class="rule-study-text">«чтобы», «не будет» и لَامٌ цели. أَنْ связывает действия, لَنْ отрицает будущее, لِـ перед глаголом означает цель. Во всех случаях الْمُضَارِعُ مَنْصُوبٌ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَنْ وَلَنْ وَلَامُ التَّعْلِيلِ</span><span class="rule-term-ru">«чтобы», «не будет» и لَامٌ цели</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَنَّ</span><span class="rule-term-ru">أَنَّ — «что»; вводит придаточное сообщение и действует как إِنَّ.</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">مَنْصُوبٌ — винительное состояние/насб.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">جِئْتُ لِأَتَعَلَّمَ.</span><span class="rule-example-ru">Я пришел, чтобы учиться.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لَنْ نَغِيبَ غَدًا.</span><span class="rule-example-ru">Мы не будем отсутствовать завтра.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '2', 'rule', '«чтобы», «не будет» и لَامٌ цели. أَنْ связывает действия, لَنْ отрицает будущее, لِـ перед глаголом означает цель. Во всех случаях الْمُضَارِعُ مَنْصُوبٌ.'),
('Мединский курс (Том 2)', '17', 'عَلَامَاتُ نَصْبِ الْمُضَارِعِ (признаки винительного состояния)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">عَلَامَاتُ نَصْبِ الْمُضَارِعِ</span><p class="rule-study-text">признаки винительного состояния. Признак — явная или предполагаемая фатха; у الْأَفْعَالُ الْخَمْسَةُ — удаление ن.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">عَلَامَاتُ نَصْبِ الْمُضَارِعِ</span><span class="rule-term-ru">признаки винительного состояния</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْأَفْعَالُ الْخَمْسَةُ</span><span class="rule-term-ru">الْأَفْعَالُ الْخَمْسَةُ — пять форм الْمُضَارِعُ с ن: يَفْعَلَانِ، تَفْعَلَانِ، يَفْعَلُونَ، تَفْعَلُونَ، تَفْعَلِينَ.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لَنْ يَكْتُبُوا.</span><span class="rule-example-ru">Они не будут писать.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '3', 'rule', 'признаки винительного состояния. Признак — явная или предполагаемая фатха; у الْأَفْعَالُ الْخَمْسَةُ — удаление ن.'),
('Мединский курс (Том 2)', '17', 'يُمْكِنُ وَمُنْذُ («возможно» и «с тех пор»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">يُمْكِنُ وَمُنْذُ</span><p class="rule-study-text">«возможно» и «с тех пор». يُمْكِنُ часто вводит أَنْ + глагол. مُنْذُ указывает начальную точку или длительность времени.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">يُمْكِنُ وَمُنْذُ</span><span class="rule-term-ru">«возможно» и «с тех пор»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَنَّ</span><span class="rule-term-ru">أَنَّ — «что»; вводит придаточное сообщение и действует как إِنَّ.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">يُمْكِنُ أَنْ نَبْدَأَ؛ مَا رَأَيْتُهُ مُنْذُ أُسْبُوعٍ.</span><span class="rule-example-ru">Мы можем начать; я не видел его неделю.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '4', 'rule', '«возможно» и «с тех пор». يُمْكِنُ часто вводит أَنْ + глагол. مُنْذُ указывает начальную точку или длительность времени.'),
('Мединский курс (Том 2)', '17', 'رَأَى يَرَى (особое спряжение «видеть»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">رَأَى يَرَى</span><p class="rule-study-text">особое спряжение «видеть». В الْمُضَارِعُ хамза основы исчезает: رَأَى → يَرَى، أَرَى، نَرَى، تَرَى.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">رَأَى يَرَى</span><span class="rule-term-ru">особое спряжение «видеть»</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أَرَى الْقَمَرَ.</span><span class="rule-example-ru">Я вижу луну.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '5', 'rule', 'особое спряжение «видеть». В الْمُضَارِعُ хамза основы исчезает: رَأَى → يَرَى، أَرَى، نَرَى، تَرَى.'),
('Мединский курс (Том 2)', '18', 'حَذْفُ النُّونِ مِنَ الْأَفْعَالِ الْخَمْسَةِ (удаление ن у пяти форм)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">حَذْفُ النُّونِ مِنَ الْأَفْعَالِ الْخَمْسَةِ</span><p class="rule-study-text">удаление ن у пяти форм. После винительных и усечных частиц формы ـانِ، ـُونَ، ـينَ теряют ن.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">حَذْفُ النُّونِ مِنَ الْأَفْعَالِ الْخَمْسَةِ</span><span class="rule-term-ru">удаление ن у пяти форм</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْأَفْعَالُ الْخَمْسَةُ</span><span class="rule-term-ru">الْأَفْعَالُ الْخَمْسَةُ — пять форм الْمُضَارِعُ с ن: يَفْعَلَانِ، تَفْعَلَانِ، يَفْعَلُونَ، تَفْعَلُونَ، تَفْعَلِينَ.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لَنْ تَكْتُبُوا؛ لَمْ تَكْتُبُوا.</span><span class="rule-example-ru">Вы не будете писать; вы не писали.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '1', 'rule', 'удаление ن у пяти форм. После винительных и усечных частиц формы ـانِ، ـُونَ، ـينَ теряют ن.'),
('Мединский курс (Том 2)', '18', 'نُونُ النِّسْوَةِ مَعَ الْمُضَارِعِ (женская ن в الْمُضَارِعُ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">نُونُ النِّسْوَةِ مَعَ الْمُضَارِعِ</span><p class="rule-study-text">женская ن в الْمُضَارِعُ. Форма с نُونٌ النِّسْوَةِ строится на сукуне и не меняется после частиц винительного или усеченного состояния.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">نُونُ النِّسْوَةِ مَعَ الْمُضَارِعِ</span><span class="rule-term-ru">женская ن в الْمُضَارِعُ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هُنَّ يَكْتُبْنَ؛ لَنْ يَكْتُبْنَ.</span><span class="rule-example-ru">Они пишут; они не будут писать.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '2', 'rule', 'женская ن в الْمُضَارِعُ. Форма с نُونٌ النِّسْوَةِ строится на сукуне и не меняется после частиц винительного или усеченного состояния.'),
('Мединский курс (Том 2)', '18', 'أَلَّا (слитное أَنْ لَا)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَلَّا</span><p class="rule-study-text">слитное أَنْ لَا. أَلَّا образуется из أَنْ + لَا. Глагол после нее остается в винительном состоянии.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَلَّا</span><span class="rule-term-ru">слитное أَنْ لَا</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَنَّ</span><span class="rule-term-ru">أَنَّ — «что»; вводит придаточное сообщение и действует как إِنَّ.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أُرِيدُ أَلَّا تَتَأَخَّرَ.</span><span class="rule-example-ru">Я хочу, чтобы ты не опаздывал.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '3', 'rule', 'слитное أَنْ لَا. أَلَّا образуется из أَنْ + لَا. Глагол после нее остается в винительном состоянии.'),
('Мединский курс (Том 2)', '18', 'كَافُ التَّشْبِيهِ (предлог сравнения كَـ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">كَافُ التَّشْبِيهِ</span><p class="rule-study-text">предлог сравнения كَـ. كَـ означает «как, подобно» и ставит следующее имя в родительный падеж.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">كَافُ التَّشْبِيهِ</span><span class="rule-term-ru">предлог сравнения كَـ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">هُوَ كَالْأَسَدِ.</span><span class="rule-example-ru">Он как лев.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '4', 'rule', 'предлог сравнения كَـ. كَـ означает «как, подобно» и ставит следующее имя в родительный падеж.'),
('Мединский курс (Том 2)', '18', 'الْأَفْعَالُ الْخَمْسَةُ (пять глагольных форм)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْأَفْعَالُ الْخَمْسَةُ</span><p class="rule-study-text">пять глагольных форм. Это الْمُضَارِعُ с أَلْفٌ الِاثْنَيْنِ, وَاوٌ الْجَمَاعَةِ или يَاءٌ الْمُخَاطَبَةِ. Они именительны с сохранением ن и винительны/усечены с ее удалением.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْأَفْعَالُ الْخَمْسَةُ</span><span class="rule-term-ru">пять глагольных форм</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هُمَا يَكْتُبَانِ، هُمْ يَكْتُبُونَ، أَنْتِ تَكْتُبِينَ.</span><span class="rule-example-ru">Они двое пишут, они пишут, ты пишешь.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '5', 'rule', 'пять глагольных форм. Это الْمُضَارِعُ с أَلْفٌ الِاثْنَيْنِ, وَاوٌ الْجَمَاعَةِ или يَاءٌ الْمُخَاطَبَةِ. Они именительны с сохранением ن и винительны/усечены с ее удалением.'),
('Мединский курс (Том 2)', '19', 'نَفْيُ الْمَاضِي وَالْحَالِ وَالْمُسْتَقْبَلِ (отрицание трех времен)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">نَفْيُ الْمَاضِي وَالْحَالِ وَالْمُسْتَقْبَلِ</span><p class="rule-study-text">отрицание трех времен. Прошедшее отрицают مَا или لَمْ + الْمُضَارِعُ, настоящее — لَا/مَا + الْمُضَارِعُ, будущее — لَنْ + الْمُضَارِعُ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">نَفْيُ الْمَاضِي وَالْحَالِ وَالْمُسْتَقْبَلِ</span><span class="rule-term-ru">отрицание трех времен</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مَا ذَهَبَ؛ لَا يَذْهَبُ؛ لَنْ يَذْهَبَ.</span><span class="rule-example-ru">Не пошел; не идет; не пойдет.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '1', 'rule', 'отрицание трех времен. Прошедшее отрицают مَا или لَمْ + الْمُضَارِعُ, настоящее — لَا/مَا + الْمُضَارِعُ, будущее — لَنْ + الْمُضَارِعُ.'),
('Мединский курс (Том 2)', '19', 'قَطُّ وَأَبَدًا («никогда» в прошлом и будущем)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">قَطُّ وَأَبَدًا</span><p class="rule-study-text">«никогда» в прошлом и будущем. قَطُّ обычно усиливает отрицание прошлого, أَبَدًا — отрицание будущего или общее отрицание.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">قَطُّ وَأَبَدًا</span><span class="rule-term-ru">«никогда» в прошлом и будущем</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مَا رَأَيْتُهُ قَطُّ؛ لَنْ أَنْسَاهُ أَبَدًا.</span><span class="rule-example-ru">Я никогда его не видел; я никогда его не забуду.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '2', 'rule', '«никогда» в прошлом и будущем. قَطُّ обычно усиливает отрицание прошлого, أَبَدًا — отрицание будущего или общее отрицание.'),
('Мединский курс (Том 2)', '20', 'الْمُثَنَّى وَإِعْرَابُهُ (двойственное число и его падежи)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمُثَنَّى وَإِعْرَابُهُ</span><p class="rule-study-text">двойственное число и его падежи. Двойственное получает ـَانِ в именительном и ـَيْنِ в винительном/родительном. ن удаляется в идафе.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْمُثَنَّى وَإِعْرَابُهُ</span><span class="rule-term-ru">двойственное число и его падежи</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْمُثَنَّى</span><span class="rule-term-ru">الْمُثَنَّى — двойственное число.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число и разряд.</li><li>Проверьте род числительного и род الْمَعْدُودُ.</li><li>Поставьте الْمَعْدُودُ в нужное число и падеж.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">جَاءَ طَالِبَانِ؛ رَأَيْتُ طَالِبَيْنِ.</span><span class="rule-example-ru">Пришли два студента; я увидел двух студентов.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя применять одно правило ко всем числам: ٣–١٠, ١١–١٩, десятки, сотни и тысячи ведут себя по-разному.</div></div>', '1', 'rule', 'двойственное число и его падежи. Двойственное получает ـَانِ в именительном и ـَيْنِ в винительном/родительном. ن удаляется в идафе.'),
('Мединский курс (Том 2)', '20', 'أَحَدُهُمَا وَالْآخَرُ («один из них и другой»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَحَدُهُمَا وَالْآخَرُ</span><p class="rule-study-text">«один из них и другой». أَحَدُهُمَا относится к одному из двух, الْآخَرُ — ко второму; обе формы получают падеж по роли.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَحَدُهُمَا وَالْآخَرُ</span><span class="rule-term-ru">«один из них и другой»</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أَحَدُهُمَا طَبِيبٌ وَالْآخَرُ مُهَنْدِسٌ.</span><span class="rule-example-ru">Один из них врач, другой инженер.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '2', 'rule', '«один из них и другой». أَحَدُهُمَا относится к одному из двух, الْآخَرُ — ко второму; обе формы получают падеж по роли.'),
('Мединский курс (Том 2)', '20', 'إِعْرَابُ ذُو وَذَاتُ (склонение ذُو и ذَاتُ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">إِعْرَابُ ذُو وَذَاتُ</span><p class="rule-study-text">склонение ذُو и ذَاتُ. ذُو имеет формы ذُو/ذَا/ذِي по трем падежам. ذَاتُ склоняется обычными огласовками и согласуется в роде.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">إِعْرَابُ ذُو وَذَاتُ</span><span class="rule-term-ru">склонение ذُو и ذَاتُ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите два связанных имени.</li><li>Первое — مُضَافٌ, второе — مُضَافٌ إِلَيْهِ.</li><li>У второго члена всегда جَرّ, а первый не принимает танвин.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مَرَرْتُ بِرَجُلٍ ذِي عِلْمٍ.</span><span class="rule-example-ru">Я прошел мимо знающего человека.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Первый член идафы не получает одновременно танвин и связь принадлежности.</div></div>', '3', 'rule', 'склонение ذُو и ذَاتُ. ذُو имеет формы ذُو/ذَا/ذِي по трем падежам. ذَاتُ склоняется обычными огласовками и согласуется в роде.'),
('Мединский курс (Том 2)', '21', 'لَمْ وَلَمَّا (отрицательные усеченные частицы)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">لَمْ وَلَمَّا</span><p class="rule-study-text">отрицательные усеченные частицы. Обе частицы усекают الْمُضَارِعُ и относят отрицание к прошлому. لَمَّا добавляет «еще не» с ожиданием действия.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَمْ وَلَمَّا</span><span class="rule-term-ru">отрицательные усеченные частицы</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لَمْ يَصِلْ؛ لَمَّا يَصِلْ.</span><span class="rule-example-ru">Он не прибыл; он еще не прибыл.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '1', 'rule', 'отрицательные усеченные частицы. Обе частицы усекают الْمُضَارِعُ и относят отрицание к прошлому. لَمَّا добавляет «еще не» с ожиданием действия.'),
('Мединский курс (Том 2)', '21', 'عَلَامَاتُ جَزْمِ الْمُضَارِعِ (признаки усеченного состояния)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">عَلَامَاتُ جَزْمِ الْمُضَارِعِ</span><p class="rule-study-text">признаки усеченного состояния. Признак — сукун, удаление слабой последней буквы или удаление ن у пяти форм.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">عَلَامَاتُ جَزْمِ الْمُضَارِعِ</span><span class="rule-term-ru">признаки усеченного состояния</span></div><div class="rule-meaning-card rule-term-jazm"><span class="rule-term-ar" dir="rtl" lang="ar">جَزْمٌ</span><span class="rule-term-ru">جَزْمٌ — усечение глагола الْمُضَارِعُ после частиц джазма.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لَمْ يَكْتُبْ؛ لَمْ يَمْشِ؛ لَمْ يَكْتُبُوا.</span><span class="rule-example-ru">Не писал; не шел; они не писали.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '2', 'rule', 'признаки усеченного состояния. Признак — сукун, удаление слабой последней буквы или удаление ن у пяти форм.'),
('Мединский курс (Том 2)', '21', 'أَقْسَامُ الْكَلِمَةِ (три части речи)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَقْسَامُ الْكَلِمَةِ</span><p class="rule-study-text">три части речи. Арабское слово относится к имени اِسْمٌ, глаголу فِعْلٌ или частице حَرْفٌ. У каждой группы свои признаки.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَقْسَامُ الْكَلِمَةِ</span><span class="rule-term-ru">три части речи</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">كِتَابٌ اِسْمٌ، كَتَبَ فِعْلٌ، فِي حَرْفٌ.</span><span class="rule-example-ru">«Книга» — имя, «написал» — глагол, «в» — частица.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '3', 'rule', 'три части речи. Арабское слово относится к имени اِسْمٌ, глаголу فِعْلٌ или частице حَرْفٌ. У каждой группы свои признаки.'),
('Мединский курс (Том 2)', '21', 'الْجُمْلَةُ الِاسْمِيَّةُ وَالْفِعْلِيَّةُ (именное и глагольное предложение)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْجُمْلَةُ الِاسْمِيَّةُ وَالْفِعْلِيَّةُ</span><p class="rule-study-text">именное и глагольное предложение. Именное начинается именем и обычно содержит مُبْتَدَأٌ/خَبَرٌ. Глагольное начинается глаголом, затем идет исполнитель и при необходимости дополнение.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْجُمْلَةُ الِاسْمِيَّةُ وَالْفِعْلِيَّةُ</span><span class="rule-term-ru">именное и глагольное предложение</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">مُبْتَدَأٌ</span><span class="rule-term-ru">مُبْتَدَأٌ — подлежащее именного предложения; обычно مَرْفُوعٍ.</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar" dir="rtl" lang="ar">خَبَرٌ</span><span class="rule-term-ru">خَبَرٌ — сказуемое/сообщение об مُبْتَدَأٌ; обычно مَرْفُوعٍ.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">الطَّالِبُ مُجْتَهِدٌ؛ كَتَبَ الطَّالِبُ الدَّرْسَ.</span><span class="rule-example-ru">Студент усердный; студент написал урок.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '4', 'rule', 'именное и глагольное предложение. Именное начинается именем и обычно содержит مُبْتَدَأٌ/خَبَرٌ. Глагольное начинается глаголом, затем идет исполнитель и при необходимости дополнение.'),
('Мединский курс (Том 2)', '21', 'اللَّاتِي وَاللَّائِي (женское множественное относительное местоимение)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">اللَّاتِي وَاللَّائِي</span><p class="rule-study-text">женское множественное относительное местоимение. Обе формы употребляются для группы женского рода и вводят поясняющее предложение.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">اللَّاتِي وَاللَّائِي</span><span class="rule-term-ru">женское множественное относительное местоимение</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">جَاءَتِ الطَّالِبَاتُ اللَّاتِي نَجَحْنَ.</span><span class="rule-example-ru">Пришли студентки, которые сдали.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '5', 'rule', 'женское множественное относительное местоимение. Обе формы употребляются для группы женского рода и вводят поясняющее предложение.'),
('Мединский курс (Том 2)', '22', 'حَالَاتُ الْمُضَارِعِ الثَّلَاثُ (три состояния الْمُضَارِعُ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">حَالَاتُ الْمُضَارِعِ الثَّلَاثُ</span><p class="rule-study-text">три состояния الْمُضَارِعُ. Без управляющей частицы глагол مَرْفُوعٌ: يَكْتُبُ. После أَنْ/لَنْ/لِـ он مَنْصُوبٌ: يَكْتُبَ. После لَمْ/لَمَّا/لَا النَّاهِيَةُ он مَجْزُومٌ: يَكْتُبْ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">حَالَاتُ الْمُضَارِعِ الثَّلَاثُ</span><span class="rule-term-ru">три состояния الْمُضَارِعُ</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَنَّ</span><span class="rule-term-ru">أَنَّ — «что»; вводит придаточное сообщение и действует как إِنَّ.</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">مَرْفُوعٌ — именительное состояние/рафʿ.</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">مَنْصُوبٌ — винительное состояние/насб.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هُوَ يَدْرُسُ؛ لَنْ يَدْرُسَ؛ لَمْ يَدْرُسْ.</span><span class="rule-example-ru">Он учится; не будет учиться; не учился.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.<br><br><b>Самопроверка.</b> Сначала найдите частицу перед глаголом, затем определите состояние и только после этого выбирайте окончание.</div></div>', '1', 'rule', 'три состояния الْمُضَارِعُ. Без управляющей частицы глагол مَرْفُوعٌ: يَكْتُبُ. После أَنْ/لَنْ/لِـ он مَنْصُوبٌ: يَكْتُبَ. После لَمْ/لَمَّا/لَا النَّاهِيَةُ он مَجْزُومٌ: يَكْتُبْ.'),
('Мединский курс (Том 2)', '23', 'إِعْرَابُ جَمْعِ الْمُذَكَّرِ السَّالِمِ (падежи правильного мужского множественного)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">إِعْرَابُ جَمْعِ الْمُذَكَّرِ السَّالِمِ</span><p class="rule-study-text">падежи правильного мужского множественного. Окончание ـُونَ используется в именительном, ـِينَ — в винительном и родительном. ن удаляется в идафе.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِعْرَابُ جَمْعِ الْمُذَكَّرِ السَّالِمِ</span><span class="rule-term-ru">падежи правильного мужского множественного</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">جَاءَ الْمُدَرِّسُونَ؛ رَأَيْتُ الْمُدَرِّسِينَ.</span><span class="rule-example-ru">Пришли учителя; я увидел учителей.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '1', 'rule', 'падежи правильного мужского множественного. Окончание ـُونَ используется в именительном, ـِينَ — в винительном и родительном. ن удаляется в идафе.'),
('Мединский курс (Том 2)', '23', 'إِعْرَابُ أَلْفَاظِ الْعُقُودِ (склонение десятков)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">إِعْرَابُ أَلْفَاظِ الْعُقُودِ</span><p class="rule-study-text">склонение десятков. عِشْرُونَ–تِسْعُونَ имеют те же падежные окончания, что и правильное мужское множественное.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">إِعْرَابُ أَلْفَاظِ الْعُقُودِ</span><span class="rule-term-ru">склонение десятков</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число и разряд.</li><li>Проверьте род числительного и род الْمَعْدُودُ.</li><li>Поставьте الْمَعْدُودُ в нужное число и падеж.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">فِي الْفَصْلِ ثَلَاثُونَ طَالِبًا؛ رَأَيْتُ ثَلَاثِينَ.</span><span class="rule-example-ru">В классе тридцать студентов; я увидел тридцать.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя применять одно правило ко всем числам: ٣–١٠, ١١–١٩, десятки, сотни и тысячи ведут себя по-разному.</div></div>', '2', 'rule', 'склонение десятков. عِشْرُونَ–تِسْعُونَ имеют те же падежные окончания, что и правильное мужское множественное.'),
('Мединский курс (Том 2)', '23', 'نَفْيُ الْمَاضِي بِـلَا (отрицание повторяющегося прошлого через لَا)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">نَفْيُ الْمَاضِي بِـلَا</span><p class="rule-study-text">отрицание повторяющегося прошлого через لَا. لَا может повторяться перед прошедшими глаголами, когда перечисляется то, чего не произошло.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">نَفْيُ الْمَاضِي بِـلَا</span><span class="rule-term-ru">отрицание повторяющегося прошлого через لَا</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число и разряд.</li><li>Проверьте род числительного и род الْمَعْدُودُ.</li><li>Поставьте الْمَعْدُودُ в нужное число и падеж.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لَا أَكَلَ وَلَا شَرِبَ.</span><span class="rule-example-ru">Он не ел и не пил.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя применять одно правило ко всем числам: ٣–١٠, ١١–١٩, десятки, сотни и тысячи ведут себя по-разному.</div></div>', '3', 'rule', 'отрицание повторяющегося прошлого через لَا. لَا может повторяться перед прошедшими глаголами, когда перечисляется то, чего не произошло.'),
('Мединский курс (Том 2)', '24', 'الْعَدَدَانِ ١ وَ٢ (числа один и два)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْعَدَدَانِ ١ وَ٢</span><p class="rule-study-text">числа один и два. Они согласуются с существительным и обычно стоят после него как прилагательные; для двух часто достаточно двойственной формы.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الْعَدَدَانِ ١ وَ٢</span><span class="rule-term-ru">числа один и два</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число и разряд.</li><li>Проверьте род числительного и род الْمَعْدُودُ.</li><li>Поставьте الْمَعْدُودُ в нужное число и падеж.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">طَالِبٌ وَاحِدٌ؛ طَالِبَتَانِ اثْنَتَانِ.</span><span class="rule-example-ru">Один студент; две студентки.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя применять одно правило ко всем числам: ٣–١٠, ١١–١٩, десятки, сотни и тысячи ведут себя по-разному.</div></div>', '1', 'rule', 'числа один и два. Они согласуются с существительным и обычно стоят после него как прилагательные; для двух часто достаточно двойственной формы.'),
('Мединский курс (Том 2)', '24', 'الْأَعْدَادُ ٣–١٠ (числа 3–10)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْأَعْدَادُ ٣–١٠</span><p class="rule-study-text">числа 3–10. Число противоположно считаемому по роду, а считаемое стоит во множественном родительном.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الْأَعْدَادُ ٣–١٠</span><span class="rule-term-ru">числа 3–10</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число и разряд.</li><li>Проверьте род числительного и род الْمَعْدُودُ.</li><li>Поставьте الْمَعْدُودُ в нужное число и падеж.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ثَلَاثَةُ كُتُبٍ؛ ثَلَاثُ سَيَّارَاتٍ.</span><span class="rule-example-ru">Три книги; три автомобиля.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя применять одно правило ко всем числам: ٣–١٠, ١١–١٩, десятки, сотни и тысячи ведут себя по-разному.</div></div>', '2', 'rule', 'числа 3–10. Число противоположно считаемому по роду, а считаемое стоит во множественном родительном.'),
('Мединский курс (Том 2)', '24', 'الْأَعْدَادُ ١١–١٩ (числа 11–19)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْأَعْدَادُ ١١–١٩</span><p class="rule-study-text">числа 11–19. В 11 и 12 обе части согласуются. В 13–19 первая часть противоположна роду, عَشَر/عَشْرَة согласуется; считаемое единственное винительное.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الْأَعْدَادُ ١١–١٩</span><span class="rule-term-ru">числа 11–19</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число и разряд.</li><li>Проверьте род числительного и род الْمَعْدُودُ.</li><li>Поставьте الْمَعْدُودُ в нужное число и падеж.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أَحَدَ عَشَرَ طَالِبًا؛ خَمْسَ عَشْرَةَ امْرَأَةً.</span><span class="rule-example-ru">Одиннадцать студентов; пятнадцать женщин.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя применять одно правило ко всем числам: ٣–١٠, ١١–١٩, десятки, сотни и тысячи ведут себя по-разному.</div></div>', '3', 'rule', 'числа 11–19. В 11 и 12 обе части согласуются. В 13–19 первая часть противоположна роду, عَشَر/عَشْرَة согласуется; считаемое единственное винительное.'),
('Мединский курс (Том 2)', '24', 'أَلْفَاظُ الْعُقُودِ وَالْمَعْطُوفُ (десятки и составные числа)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَلْفَاظُ الْعُقُودِ وَالْمَعْطُوفُ</span><p class="rule-study-text">десятки и составные числа. Десятки склоняются через و/ي, единица соединяется с ними через وَ. Считаемое всегда единственное винительное.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَلْفَاظُ الْعُقُودِ وَالْمَعْطُوفُ</span><span class="rule-term-ru">десятки и составные числа</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число и разряд.</li><li>Проверьте род числительного и род الْمَعْدُودُ.</li><li>Поставьте الْمَعْدُودُ в нужное число и падеж.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ثَلَاثَةٌ وَعِشْرُونَ كِتَابًا.</span><span class="rule-example-ru">Двадцать три книги.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя применять одно правило ко всем числам: ٣–١٠, ١١–١٩, десятки, сотни и тысячи ведут себя по-разному.</div></div>', '4', 'rule', 'десятки и составные числа. Десятки склоняются через و/ي, единица соединяется с ними через وَ. Считаемое всегда единственное винительное.'),
('Мединский курс (Том 2)', '24', 'الْمِئَاتُ وَالْآلَافُ (сотни и тысячи)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمِئَاتُ وَالْآلَافُ</span><p class="rule-study-text">сотни и тысячи. После сотен и тысяч считаемое единственное родительное. В 300–900 и 3000–9000 первая часть подчиняется правилу 3–10.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْمِئَاتُ وَالْآلَافُ</span><span class="rule-term-ru">сотни и тысячи</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число и разряд.</li><li>Проверьте род числительного и род الْمَعْدُودُ.</li><li>Поставьте الْمَعْدُودُ в нужное число и падеж.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ثَلَاثُمِائَةِ كِتَابٍ؛ خَمْسَةُ آلَافِ طَالِبٍ.</span><span class="rule-example-ru">Триста книг; пять тысяч студентов.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя применять одно правило ко всем числам: ٣–١٠, ١١–١٩, десятки, сотни и тысячи ведут себя по-разному.</div></div>', '5', 'rule', 'сотни и тысячи. После сотен и тысяч считаемое единственное родительное. В 300–900 и 3000–9000 первая часть подчиняется правилу 3–10.'),
('Мединский курс (Том 2)', '25', 'كَانَ وَمَا زَالَ («был» и «все еще»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">كَانَ وَمَا زَالَ</span><p class="rule-study-text">«был» и «все еще». Оба نَاقِصٌных глагола оставляют имя именительным и ставят сказуемое в винительный. كَانَ переносит состояние в прошлое, مَا زَالَ показывает продолжение.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">كَانَ وَمَا زَالَ</span><span class="rule-term-ru">«был» и «все еще»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">كَانَ</span><span class="rule-term-ru">كَانَ — «был/была»; её имя в رَفْع, خَبَرٌ в نَصْب.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">كَانَ الْبَابُ مَفْتُوحًا؛ مَا زَالَ الطَّالِبُ مَرِيضًا.</span><span class="rule-example-ru">Дверь была открыта; студент все еще болен.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '1', 'rule', '«был» и «все еще». Оба نَاقِصٌных глагола оставляют имя именительным и ставят сказуемое в винительный. كَانَ переносит состояние в прошлое, مَا زَالَ показывает продолжение.'),
('Мединский курс (Том 2)', '25', 'الْأَسْمَاءُ الْخَمْسَةُ (пять особых имен)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْأَسْمَاءُ الْخَمْسَةُ</span><p class="rule-study-text">пять особых имен. أَبٌ، أَخٌ، حَمٌ، فُو، ذُو при выполнении условий склоняются буквами: و в именительном, ا в винительном, ي в родительном.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْأَسْمَاءُ الْخَمْسَةُ</span><span class="rule-term-ru">пять особых имен</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите два связанных имени.</li><li>Первое — مُضَافٌ, второе — مُضَافٌ إِلَيْهِ.</li><li>У второго члена всегда جَرّ, а первый не принимает танвин.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">جَاءَ أَبُوكَ؛ رَأَيْتُ أَبَاكَ؛ سَلَّمْتُ عَلَى أَبِيكَ.</span><span class="rule-example-ru">Твой отец пришел; я увидел и поприветствовал твоего отца.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Первый член идафы не получает одновременно танвин и связь принадлежности.</div></div>', '2', 'rule', 'пять особых имен. أَبٌ، أَخٌ، حَمٌ، فُو، ذُو при выполнении условий склоняются буквами: و в именительном, ا в винительном, ي в родительном.'),
('Мединский курс (Том 2)', '25', 'شُرُوطُ الْأَسْمَاءِ الْخَمْسَةِ (условия склонения пяти имен)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">شُرُوطُ الْأَسْمَاءِ الْخَمْسَةِ</span><p class="rule-study-text">условия склонения пяти имен. Форма должна быть единственной, не уменьшительной и находиться в идафе не к ي говорящего. Иначе используются обычные огласовки.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">شُرُوطُ الْأَسْمَاءِ الْخَمْسَةِ</span><span class="rule-term-ru">условия склонения пяти имен</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْأَسْمَاءُ الْخَمْسَةُ</span><span class="rule-term-ru">الْأَسْمَاءُ الْخَمْسَةُ — пять имён, склоняемых буквами: أَبٌ، أَخٌ، حَمٌ، فُو، ذُو.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا أَخُو مُحَمَّدٍ.</span><span class="rule-example-ru">Это брат Мухаммада.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '3', 'rule', 'условия склонения пяти имен. Форма должна быть единственной, не уменьшительной и находиться в идафе не к ي говорящего. Иначе используются обычные огласовки.'),
('Мединский курс (Том 2)', '26', 'الْفِعْلُ الْمِثَالُ الْوَاوِيُّ (слабый глагол с و в начале)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْفِعْلُ الْمِثَالُ الْوَاوِيُّ</span><p class="rule-study-text">слабый глагол с و в начале. В الْمُضَارِعُ ряда глаголов начальная و выпадает: وَعَدَ يَعِدُ، وَصَلَ يَصِلُ. В прошедшем она сохраняется; в повелительном не возвращается.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْفِعْلُ الْمِثَالُ الْوَاوِيُّ</span><span class="rule-term-ru">слабый глагол с و в начале</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">وَصَلَ الْقِطَارُ؛ يَصِلُ غَدًا؛ عِدْ.</span><span class="rule-example-ru">Поезд прибыл; прибудет завтра; обещай.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '1', 'rule', 'слабый глагол с و в начале. В الْمُضَارِعُ ряда глаголов начальная و выпадает: وَعَدَ يَعِدُ، وَصَلَ يَصِلُ. В прошедшем она сохраняется; в повелительном не возвращается.'),
('Мединский курс (Том 2)', '26', 'التَّصْغِيرُ (уменьшительная форма)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">التَّصْغِيرُ</span><p class="rule-study-text">уменьшительная форма. Трехбуквенное имя часто получает модель فُعَيْلٌ, передающую малый размер или ласковое отношение.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">التَّصْغِيرُ</span><span class="rule-term-ru">уменьшительная форма</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">كِتَابٌ → كُتَيِّبٌ.</span><span class="rule-example-ru">Книга → книжечка.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '2', 'rule', 'уменьшительная форма. Трехбуквенное имя часто получает модель فُعَيْلٌ, передающую малый размер или ласковое отношение.'),
('Мединский курс (Том 2)', '26', 'اسْمُ التَّفْضِيلِ مِنَ الْمُضَعَّفِ (сравнительная степень удвоенного глагола)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">اسْمُ التَّفْضِيلِ مِنَ الْمُضَعَّفِ</span><p class="rule-study-text">сравнительная степень удвоенного глагола. При построении أَفْعَلُ две одинаковые коренные буквы сохраняют удвоение.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">اسْمُ التَّفْضِيلِ مِنَ الْمُضَعَّفِ</span><span class="rule-term-ru">сравнительная степень удвоенного глагола</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">شَدَّ → أَشَدُّ.</span><span class="rule-example-ru">Быть сильным → сильнее.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '3', 'rule', 'сравнительная степень удвоенного глагола. При построении أَفْعَلُ две одинаковые коренные буквы сохраняют удвоение.'),
('Мединский курс (Том 2)', '26', 'هَا هُوَ ذَا (оборот «вот он»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">هَا هُوَ ذَا</span><p class="rule-study-text">оборот «вот он». هَا привлекает внимание, затем идет местоимение и указательное слово, согласованные с лицом и родом.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَا هُوَ ذَا</span><span class="rule-term-ru">оборот «вот он»</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">هَا هُوَ ذَا؛ هَا هِيَ ذِهِ.</span><span class="rule-example-ru">Вот он; вот она.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '4', 'rule', 'оборот «вот он». هَا привлекает внимание, затем идет местоимение и указательное слово, согласованные с лицом и родом.'),
('Мединский курс (Том 2)', '26', 'يَجِبُ وَمَصْدَرُ ذَهَبَ («необходимо» и масдар ذَهَبَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">يَجِبُ وَمَصْدَرُ ذَهَبَ</span><p class="rule-study-text">«необходимо» и масдар ذَهَبَ. После يَجِبُ часто употребляется أَنْ + الْمُضَارِعُ. Масдар ذَهَبَ — ذَهَابٌ и запоминается словарно.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">يَجِبُ وَمَصْدَرُ ذَهَبَ</span><span class="rule-term-ru">«необходимо» и масдар ذَهَبَ</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَنَّ</span><span class="rule-term-ru">أَنَّ — «что»; вводит придаточное сообщение и действует как إِنَّ.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">يَجِبُ أَنْ تَذْهَبَ؛ أُرِيدُ الذَّهَابَ.</span><span class="rule-example-ru">Тебе нужно пойти; я хочу пойти.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '5', 'rule', '«необходимо» и масдар ذَهَبَ. После يَجِبُ часто употребляется أَنْ + الْمُضَارِعُ. Масдар ذَهَبَ — ذَهَابٌ и запоминается словарно.'),
('Мединский курс (Том 2)', '27', 'الْفِعْلُ الْأَجْوَفُ (пустой глагол со слабой средней буквой)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْفِعْلُ الْأَجْوَفُ</span><p class="rule-study-text">пустой глагол со слабой средней буквой. У глагола типа قَالَ/بَاعَ средняя و или ي превращается в долгую ا в одних формах и сокращается в других.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْفِعْلُ الْأَجْوَفُ</span><span class="rule-term-ru">пустой глагол со слабой средней буквой</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">قَالَ يَقُولُ؛ بَاعَ يَبِيعُ.</span><span class="rule-example-ru">Сказать; продавать.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '1', 'rule', 'пустой глагол со слабой средней буквой. У глагола типа قَالَ/بَاعَ средняя و или ي превращается в долгую ا в одних формах и сокращается в других.'),
('Мединский курс (Том 2)', '27', 'إِسْنَادُ الْأَجْوَفِ فِي الْمَاضِي (прошедшее пустого глагола)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">إِسْنَادُ الْأَجْوَفِ فِي الْمَاضِي</span><p class="rule-study-text">прошедшее пустого глагола. Перед подвижным окончанием долгий гласный сокращается: قَالَ, но قُلْتُ; بَاعَ, но بِعْتُ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِسْنَادُ الْأَجْوَفِ فِي الْمَاضِي</span><span class="rule-term-ru">прошедшее пустого глагола</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">قَالُوا وَقُلْنَا.</span><span class="rule-example-ru">Они сказали, и мы сказали.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '2', 'rule', 'прошедшее пустого глагола. Перед подвижным окончанием долгий гласный сокращается: قَالَ, но قُلْتُ; بَاعَ, но بِعْتُ.'),
('Мединский курс (Том 2)', '27', 'الْأَجْوَفُ فِي الْمُضَارِعِ وَالْأَمْرِ (пустой глагол в الْمُضَارِعُ и повелительном)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْأَجْوَفُ فِي الْمُضَارِعِ وَالْأَمْرِ</span><p class="rule-study-text">пустой глагол в الْمُضَارِعُ и повелительном. В именительном/винительном долгий гласный сохраняется, а в усеченном перед сукуном выпадает. Повелительное берется от усеченной формы.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْأَجْوَفُ فِي الْمُضَارِعِ وَالْأَمْرِ</span><span class="rule-term-ru">пустой глагол в الْمُضَارِعُ и повелительном</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">يَقُولُ، لَنْ يَقُولَ، لَمْ يَقُلْ، قُلْ.</span><span class="rule-example-ru">Говорит; не будет говорить; не говорил; скажи.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '3', 'rule', 'пустой глагол в الْمُضَارِعُ и повелительном. В именительном/винительном долгий гласный сохраняется, а в усеченном перед сукуном выпадает. Повелительное берется от усеченной формы.'),
('Мединский курс (Том 2)', '27', 'أَصْلُ الْحَرْفِ الْمُعْتَلِّ (как определить و или ي в корне)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَصْلُ الْحَرْفِ الْمُعْتَلِّ</span><p class="rule-study-text">как определить و или ي в корне. Смотрите на الْمُضَارِعُ или масдар: قَالَ يَقُولُ указывает на و, بَاعَ يَبِيعُ — на ي.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَصْلُ الْحَرْفِ الْمُعْتَلِّ</span><span class="rule-term-ru">как определить و или ي в корне</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите مَنْعُوتٌ — определяемое слово.</li><li>Поставьте после него نَعْتٌ.</li><li>Согласуйте نَعْتٌ в падеже, определённости, роде и числе.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">صَامَ يَصُومُ: الْجَذْرُ ص و م.</span><span class="rule-example-ru">Поститься: корень ص و م.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя переводить прилагательное отдельно от определяемого слова: его окончание зависит от مَنْعُوت.</div></div>', '4', 'rule', 'как определить و или ي в корне. Смотрите на الْمُضَارِعُ или масдар: قَالَ يَقُولُ указывает на و, بَاعَ يَبِيعُ — на ي.'),
('Мединский курс (Том 2)', '27', 'الْقَسَمُ وَلَقَدْ وَظَنَّ (клятва, усиление и два дополнения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْقَسَمُ وَلَقَدْ وَظَنَّ</span><p class="rule-study-text">клятва, усиление и два дополнения. После وَاللهِ утверждение часто усиливается لَـ/قَدْ. ظَنَّ ставит два дополнения в винительный: кого считаем и кем.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الْقَسَمُ وَلَقَدْ وَظَنَّ</span><span class="rule-term-ru">клятва, усиление и два дополнения</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">وَاللهِ لَقَدْ صَدَقَ؛ ظَنَنْتُ خَالِدًا طَبِيبًا.</span><span class="rule-example-ru">Клянусь Аллахом, он сказал правду; я считал Халида врачом.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '5', 'rule', 'клятва, усиление и два дополнения. После وَاللهِ утверждение часто усиливается لَـ/قَدْ. ظَنَّ ставит два дополнения в винительный: кого считаем и кем.'),
('Мединский курс (Том 2)', '28', 'الْفِعْلُ النَّاقِصُ (слабый глагол с последней و/ي)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْفِعْلُ النَّاقِصُ</span><p class="rule-study-text">слабый глагол с последней و/ي. Последняя слабая буква меняется по форме: دَعَا يَدْعُو، رَمَى يَرْمِي. Вид буквы определяется الْمُضَارِعُ и масдаром.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْفِعْلُ النَّاقِصُ</span><span class="rule-term-ru">слабый глагол с последней و/ي</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هَدَى يَهْدِي؛ دَعَا يَدْعُو.</span><span class="rule-example-ru">Вести прямым путем; звать.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '1', 'rule', 'слабый глагол с последней و/ي. Последняя слабая буква меняется по форме: دَعَا يَدْعُو، رَمَى يَرْمِي. Вид буквы определяется الْمُضَارِعُ и масдаром.'),
('Мединский курс (Том 2)', '28', 'إِسْنَادُ النَّاقِصِ فِي الْمَاضِي (прошедшее слабого конечного глагола)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">إِسْنَادُ النَّاقِصِ فِي الْمَاضِي</span><p class="rule-study-text">прошедшее слабого конечного глагола. Перед некоторыми окончаниями слабая буква меняется или выпадает: دَعَوْتُ، رَمَيْتُ، دَعَوْا، رَمَوْا.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِسْنَادُ النَّاقِصِ فِي الْمَاضِي</span><span class="rule-term-ru">прошедшее слабого конечного глагола</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">رَمَيْتُ الْكُرَةَ.</span><span class="rule-example-ru">Я бросил мяч.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '2', 'rule', 'прошедшее слабого конечного глагола. Перед некоторыми окончаниями слабая буква меняется или выпадает: دَعَوْتُ، رَمَيْتُ، دَعَوْا، رَمَوْا.'),
('Мединский курс (Том 2)', '28', 'النَّاقِصُ فِي الْمُضَارِعِ وَالْأَمْرِ (конечнослабый глагол в الْمُضَارِعُ и повелительном)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">النَّاقِصُ فِي الْمُضَارِعِ وَالْأَمْرِ</span><p class="rule-study-text">конечнослабый глагол в الْمُضَارِعُ и повелительном. В именительном слабая буква сохраняется, в усеченном и повелительном удаляется; в винительном появляется фатха перед ней.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">النَّاقِصُ فِي الْمُضَارِعِ وَالْأَمْرِ</span><span class="rule-term-ru">конечнослабый глагол в الْمُضَارِعُ и повелительном</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">يَمْشِي، لَنْ يَمْشِيَ، لَمْ يَمْشِ، اِمْشِ.</span><span class="rule-example-ru">Идет; не пойдет; не шел; иди.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '3', 'rule', 'конечнослабый глагол в الْمُضَارِعُ и повелительном. В именительном слабая буква сохраняется, в усеченном и повелительном удаляется; в винительном появляется фатха перед ней.'),
('Мединский курс (Том 2)', '28', 'رَأَى وَأَرِنِي («увидел» и «покажи мне»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">رَأَى وَأَرِنِي</span><p class="rule-study-text">«увидел» и «покажи мне». رَأَى имеет особые изменения хамзы. Повелительное четвертой породы أَرَى — أَرِ, а с объектом: أَرِنِي.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">رَأَى وَأَرِنِي</span><span class="rule-term-ru">«увидел» и «покажи мне»</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أَرِنِي كِتَابَكَ.</span><span class="rule-example-ru">Покажи мне свою книгу.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '4', 'rule', '«увидел» и «покажи мне». رَأَى имеет особые изменения хамзы. Повелительное четвертой породы أَرَى — أَرِ, а с объектом: أَرِنِي.'),
('Мединский курс (Том 2)', '29', 'الْفِعْلُ الْمُضَعَّفُ (удвоенный глагол)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْفِعْلُ الْمُضَعَّفُ</span><p class="rule-study-text">удвоенный глагол. Если вторая и третья коренные одинаковы, они сливаются под шаддой: رَدَّ، يَرُدُّ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْفِعْلُ الْمُضَعَّفُ</span><span class="rule-term-ru">удвоенный глагол</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">رَدَّ الطَّالِبُ الْكِتَابَ.</span><span class="rule-example-ru">Студент вернул книгу.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '1', 'rule', 'удвоенный глагол. Если вторая и третья коренные одинаковы, они сливаются под шаддой: رَدَّ، يَرُدُّ.'),
('Мединский курс (Том 2)', '29', 'إِسْنَادُ الْمُضَعَّفِ فِي الْمَاضِي (прошедшее удвоенного глагола)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">إِسْنَادُ الْمُضَعَّفِ فِي الْمَاضِي</span><p class="rule-study-text">прошедшее удвоенного глагола. Перед окончанием с сукуном шадда раскрывается: رَدَدْتُ، رَدَدْنَا. Без такого окончания остается رَدَّ، رَدُّوا.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">إِسْنَادُ الْمُضَعَّفِ فِي الْمَاضِي</span><span class="rule-term-ru">прошедшее удвоенного глагола</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">ظَنَنْتُ؛ ظَنُّوا.</span><span class="rule-example-ru">Я подумал; они подумали.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '2', 'rule', 'прошедшее удвоенного глагола. Перед окончанием с сукуном шадда раскрывается: رَدَدْتُ، رَدَدْنَا. Без такого окончания остается رَدَّ، رَدُّوا.'),
('Мединский курс (Том 2)', '29', 'الْمُضَعَّفُ فِي الْمُضَارِعِ وَالْأَمْرِ (удвоенный глагол в الْمُضَارِعُ и повелительном)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمُضَعَّفُ فِي الْمُضَارِعِ وَالْأَمْرِ</span><p class="rule-study-text">удвоенный глагол в الْمُضَارِعُ и повелительном. В обычной форме шадда сохраняется. В усеченном возможна форма с раскрытием; повелительное обычно сохраняет удвоение.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْمُضَعَّفُ فِي الْمُضَارِعِ وَالْأَمْرِ</span><span class="rule-term-ru">удвоенный глагол в الْمُضَارِعُ и повелительном</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">يَرُدُّ، لَنْ يَرُدَّ، لَمْ يَرُدَّ/يَرْدُدْ، رُدَّ.</span><span class="rule-example-ru">Возвращает; не будет; не вернул; верни.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '3', 'rule', 'удвоенный глагол в الْمُضَارِعُ и повелительном. В обычной форме шадда сохраняется. В усеченном возможна форма с раскрытием; повелительное обычно сохраняет удвоение.'),
('Мединский курс (Том 2)', '29', 'قَطُّ وَأَبَدًا (наречия усиления отрицания)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">قَطُّ وَأَبَدًا</span><p class="rule-study-text">наречия усиления отрицания. قَطُّ относится преимущественно к прошлому, أَبَدًا — к будущему; выбирайте по времени.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">قَطُّ وَأَبَدًا</span><span class="rule-term-ru">наречия усиления отрицания</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок и русский смысл.</li><li>Найдите эту конструкцию в примере.</li><li>Проверьте роль слов: اِسْمٌ، خَبَرٌ، فَاعِلٌ، مَفْعُولٌ بِهِ, затем окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لَمْ أَكْذِبْ قَطُّ؛ لَنْ أَكْذِبَ أَبَدًا.</span><span class="rule-example-ru">Я никогда не лгал; я никогда не буду лгать.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не разбирайте окончание вне предложения: сначала установите функцию слова, потом падеж или наклонение.</div></div>', '4', 'rule', 'наречия усиления отрицания. قَطُّ относится преимущественно к прошлому, أَبَدًا — к будущему; выбирайте по времени.'),
('Мединский курс (Том 2)', '29', 'مُرَاجَعَةُ الْأَفْعَالِ الْمُعْتَلَّةِ (сводка слабых глаголов)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مُرَاجَعَةُ الْأَفْعَالِ الْمُعْتَلَّةِ</span><p class="rule-study-text">сводка слабых глаголов. مِثَالٌ имеет слабую первую, أَجْوَفُ — среднюю, نَاقِصٌ — последнюю коренную. Место слабой буквы определяет изменения.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مُرَاجَعَةُ الْأَفْعَالِ الْمُعْتَلَّةِ</span><span class="rule-term-ru">сводка слабых глаголов</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">وَعَدَ مِثَالٌ، قَالَ أَجْوَفُ، دَعَا نَاقِصٌ.</span><span class="rule-example-ru">Обещать — начально-слабый; говорить — пустой; звать — конечнослабый.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '5', 'rule', 'сводка слабых глаголов. مِثَالٌ имеет слабую первую, أَجْوَفُ — среднюю, نَاقِصٌ — последнюю коренную. Место слабой буквы определяет изменения.'),
('Мединский курс (Том 2)', '30', 'أَلِفُ الِاثْنَيْنِ فِي الْأَفْعَالِ (двойственное число глагола)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَلِفُ الِاثْنَيْنِ فِي الْأَفْعَالِ</span><p class="rule-study-text">двойственное число глагола. Для «они двое» и «вы двое» используются формы ذَهَبَا، ذَهَبَتَا، يَذْهَبَانِ، تَذْهَبَانِ، اِذْهَبَا، لَا تَذْهَبَا.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَلِفُ الِاثْنَيْنِ فِي الْأَفْعَالِ</span><span class="rule-term-ru">двойственное число глагола</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число и разряд.</li><li>Проверьте род числительного и род الْمَعْدُودُ.</li><li>Поставьте الْمَعْدُودُ в нужное число и падеж.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">الطَّالِبَانِ ذَهَبَا وَالطَّالِبَتَانِ ذَهَبَتَا.</span><span class="rule-example-ru">Два студента ушли, и две студентки ушли.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя применять одно правило ко всем числам: ٣–١٠, ١١–١٩, десятки, сотни и тысячи ведут себя по-разному.</div></div>', '1', 'rule', 'двойственное число глагола. Для «они двое» и «вы двое» используются формы ذَهَبَا، ذَهَبَتَا، يَذْهَبَانِ، تَذْهَبَانِ، اِذْهَبَا، لَا تَذْهَبَا.'),
('Мединский курс (Том 2)', '30', 'الْمُثَنَّى مِنَ الْأَفْعَالِ الْخَمْسَةِ (двойственные формы среди пяти глаголов)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمُثَنَّى مِنَ الْأَفْعَالِ الْخَمْسَةِ</span><p class="rule-study-text">двойственные формы среди пяти глаголов. يَفْعَلَانِ и تَفْعَلَانِ именительны с ن; после أَنْ، لَنْ، لَمْ и запрета ن удаляется.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْمُثَنَّى مِنَ الْأَفْعَالِ الْخَمْسَةِ</span><span class="rule-term-ru">двойственные формы среди пяти глаголов</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَنَّ</span><span class="rule-term-ru">أَنَّ — «что»; вводит придаточное сообщение и действует как إِنَّ.</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْأَفْعَالُ الْخَمْسَةُ</span><span class="rule-term-ru">الْأَفْعَالُ الْخَمْسَةُ — пять форм الْمُضَارِعُ с ن: يَفْعَلَانِ، تَفْعَلَانِ، يَفْعَلُونَ، تَفْعَلُونَ، تَفْعَلِينَ.</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْمُثَنَّى</span><span class="rule-term-ru">الْمُثَنَّى — двойственное число.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите корень и тип глагола.</li><li>Определите время, лицо, число и род.</li><li>Проверьте конечное состояние: رَفْع، نَصْب или جَزْم.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هُمَا يَكْتُبَانِ؛ لَنْ يَكْتُبَا؛ لَمْ يَكْتُبَا.</span><span class="rule-example-ru">Они двое пишут; не будут писать; не писали.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не ориентируйтесь только на русский перевод: арабская приставка, окончание и частица перед глаголом решают форму.</div></div>', '2', 'rule', 'двойственные формы среди пяти глаголов. يَفْعَلَانِ и تَفْعَلَانِ именительны с ن; после أَنْ، لَنْ، لَمْ и запрета ن удаляется.'),
('Мединский курс (Том 2)', '31', 'النَّعْتُ وَالْمَنْعُوتُ (прилагательное и определяемое имя)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">النَّعْتُ وَالْمَنْعُوتُ</span><p class="rule-study-text">прилагательное и определяемое имя. Прилагательное следует после существительного и описывает его. Определяемое имя называется مَنْعُوت, определение — نَعْت.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">النَّعْتُ وَالْمَنْعُوتُ</span><span class="rule-term-ru">прилагательное и определяемое имя</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">نَعْتٌ</span><span class="rule-term-ru">نَعْتٌ — определение/прилагательное после определяемого слова.</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْعُوتٌ</span><span class="rule-term-ru">مَنْعُوتٌ — определяемое слово, к которому относится نَعْت.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите مَنْعُوتٌ — определяемое слово.</li><li>Поставьте после него نَعْتٌ.</li><li>Согласуйте نَعْتٌ в падеже, определённости, роде и числе.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">جَاءَ طَالِبٌ جَدِيدٌ.</span><span class="rule-example-ru">Пришел новый студент.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя переводить прилагательное отдельно от определяемого слова: его окончание зависит от مَنْعُوت.</div></div>', '1', 'rule', 'прилагательное и определяемое имя. Прилагательное следует после существительного и описывает его. Определяемое имя называется مَنْعُوت, определение — نَعْت.'),
('Мединский курс (Том 2)', '31', 'مُطَابَقَةُ النَّعْتِ لِلْمَنْعُوتِ (согласование определения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مُطَابَقَةُ النَّعْتِ لِلْمَنْعُوتِ</span><p class="rule-study-text">согласование определения. Определение согласуется в четырех признаках: падеже, определенности, роде и числе.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مُطَابَقَةُ النَّعْتِ لِلْمَنْعُوتِ</span><span class="rule-term-ru">согласование определения</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число и разряд.</li><li>Проверьте род числительного и род الْمَعْدُودُ.</li><li>Поставьте الْمَعْدُودُ в нужное число и падеж.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">رَأَيْتُ الطَّالِبَةَ الْجَدِيدَةَ.</span><span class="rule-example-ru">Я увидел новую студентку.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя применять одно правило ко всем числам: ٣–١٠, ١١–١٩, десятки, сотни и тысячи ведут себя по-разному.</div></div>', '2', 'rule', 'согласование определения. Определение согласуется в четырех признаках: падеже, определенности, роде и числе.'),
('Мединский курс (Том 2)', '31', 'نَعْتُ جَمْعِ غَيْرِ الْعَاقِلِ (определение неодушевленного множественного)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">نَعْتُ جَمْعِ غَيْرِ الْعَاقِلِ</span><p class="rule-study-text">определение неодушевленного множественного. Неодушевленное множественное обычно получает определение женского единственного рода.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">نَعْتُ جَمْعِ غَيْرِ الْعَاقِلِ</span><span class="rule-term-ru">определение неодушевленного множественного</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">نَعْتٌ</span><span class="rule-term-ru">نَعْتٌ — определение/прилагательное после определяемого слова.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите مَنْعُوتٌ — определяемое слово.</li><li>Поставьте после него نَعْتٌ.</li><li>Согласуйте نَعْتٌ в падеже, определённости, роде и числе.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">هَذِهِ كُتُبٌ جَدِيدَةٌ.</span><span class="rule-example-ru">Это новые книги.</span></div></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя переводить прилагательное отдельно от определяемого слова: его окончание зависит от مَنْعُوت.</div></div>', '3', 'rule', 'определение неодушевленного множественного. Неодушевленное множественное обычно получает определение женского единственного рода.');
